insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('dea-zoeoed-an-jeedn-schdich-nooch-wiara-quaaglschdecha-spueued-owa-wiara-waeae', 'Dea zööd an jeedn Schdich nooch wiara Quaaglschdecha, spüüd owa wiara Wää!', '', '', '', 'Wiener Kartentipplerjargon', 'Der zählt einen jeden Stich nach wie ein Quargelstecher, spielt aber wie ein Weh!', '[{"kategorie": "wörtlich", "text": "\"Der zählt jeden Stich nach wie ein Steuerprüfer, spielt aber selbst wie ein Anfänger!\"  2. \"Der zählt jeden Stich nach wie ein Buchhalter, gewinnt aber trotzdem nie!\"  3. \"Der zählt jeden Stich nach wie ein Korinthenkacker, spielt aber selbst wie ein Wappler!\""}]'::jsonb, ''),
  ('wem-untan-quaaglschduaz-schdoeoen', 'wem untan Quaaglschduaz schdöön', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden unter den Quargelsturz stellen', '[{"kategorie": "wörtlich", "text": "\"jemanden unter die Käseglocke stellen\""}, {"kategorie": "fig.", "text": "\"jemanden unter einen Glassturz stellen\""}, {"kategorie": "", "text": "\"jemanden in Watte packen\""}, {"kategorie": "", "text": "\"jemanden in eine Glaskugel packen\""}]'::jsonb, 'Soi I di leicht untan Quaaglschduaz schdöön - nua wäusd glei de Panik kriagsd, waunns Leebm moi huast?'),
  ('soi-i-di-leicht-untan-quaaglschduaz-schdoeoen-nua-waeusd-glei-de-panik-kriagsd-waunns-leebm-moi-huast', 'Soi I di leicht untan Quaaglschduaz schdöön - nua wäusd glei de Panik kriagsd, waunns Leebm moi huast?', '', '', '', 'Wiener Gaunersprache', 'Soll ich dich vielleicht unter einen Quargelsturz stellen - nur weil du die Panik kriegst, wenn das Leben mal hustet?', '[{"kategorie": "wörtlich", "text": "\"Soll ich dich etwa unter eine Käseglocke stellen - nur weil du gleich die Panik kriegst, wenn das Leben mal hustet?\"  2. \"Soll ich dich etwa in eine Glaskugel packen, nur weil du bei jedem kleinen Schreck gleich die Panik kriegst?\"  3. \"Soll ich dich etwa unter einen Glassturz stellen, nur weil du in Panik gerätst, sobald das Leben mal niest?\""}]'::jsonb, 'wem untan Quaaglschduaz schdöön'),
  ('deck-de-quaagltreeda-zua-sunst-kippt-uns-noo-wea-um', 'Deck de Quaagltreeda zua, sunst kippt uns noo wea um!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Deck die Quargeltreter zu, sonst kippt uns noch wer um!', '[{"kategorie": "wörtlich", "text": "\"Deck die Stinktreter ab, bevor uns hier noch einer kollabiert!\"  2. \"Leg was über deine Käsefüße, bevor uns noch jemand ohnmächtig wird!\"  3. \"Wenn du deine Stinkfüße nicht sofort zudeckst, braucht''s gleich ''nen Sanitäter!\""}]'::jsonb, ''),
  ('fia-soiche-quaagltreeda-findsd-in-kaan-gschaefd-noamale-schuach', 'Fia soiche Quaagltreeda findsd in kaan Gschäfd noamale Schuach!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Für solche Quargeltreter findest du in keinem Geschäft normale Schuhe!', '[{"kategorie": "wörtlich", "text": "\"Mit solchen Riesenfüßen wirst du in keinem Geschäft normale Schuhe finden!\"  2. \"Mit [[Rinnsaldampfern]] in der Größe gibt’s kaum normale Schuhe zu kaufen!\"  3. \"Für solche Monsterlatschen hat kein Geschäft was im Regal!\""}]'::jsonb, ''),
  ('mit-so-an-quaagltreeda-mochd-ned-amoi-mea-kaffeetrinkn-schbaass', 'Mit so an Quaagltreeda mochd ned amoi mea Kaffeetrinkn Schbaass!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Mit so einem Quargeltreter macht nicht einmal mehr Kaffeetrinken Spaß!', '[{"kategorie": "wörtlich", "text": "\"Mit so einem Nörgler macht selbst Kaffeetrinken keinen Spaß mehr!\"  2. \"Mit dem Korinthenkacker wird jede Kaffeepause zur Strafe!\"  3. \"Mit so einem [[Grantler]] kannst du nicht einmal mehr in Ruhe deinen Kaffee trinken!\""}]'::jsonb, ''),
  ('deine-quaaglhaxn-soitasd-moi-ind-klaeaaunloog-hoidn-aum-bestn-mid-an-woanschueued', 'Deine Quaaglhaxn soitasd moi ind Kläaaunloog hoidn - aum bestn mid an Woanschüüd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Deine Quargelhaxen solltest du mal in die Kläranlage halten - am besten mit einem Warnschild!', '[{"kategorie": "wörtlich", "text": "\"Deine Quargeltreter gehören direkt ins Klärbecken – am besten mit Warnschild!\"  2. \"Diese Käsefüße gehören nicht gelüftet - die gehören ins Klärwerk, inklusive Nachbehandlung!\"  3. \"Diese Stinkefüße gehören nicht gewaschen, die gehören entsorgt – in der Durchlaufanlage vom Klärwerk!\""}]'::jsonb, ''),
  ('kaeu-ausetzn-und-vuasichtig-quaan-damits-material-gleichmaeaessich-noochgibd', 'Käu ausetzn und vuasichtig quaan, damits Material gleichmäässich noochgibd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Keil ansetzen und vorsichtig quaren, damit das Material gleichmäßig nachgibt!', '[{"kategorie": "wörtlich", "text": "\"Keil ansetzen und langsam spreizen, damit der Werkstoff gleichmäßig nachgibt!\"  2. \"Mit dem Keil vorsichtig aufspreizen, bis sich das Material gleichmäßig öffnet!\"  3. \"Den Keil behutsam treiben und kontrolliert aufspreizen, damit sich die Spannung gleichmäßig verteilt!\""}]'::jsonb, ''),
  ('noo-kaa-schdich-draussn-und-dea-querulant-faungd-schoo-zum-dischkutian-au', 'Noo kaa Schdich draussn, und dea Querulant faungd schoo zum Dischkutian au!', '', '', '', 'Wiener Kartentipplerjargon', 'Noch kein Stich draußen, und der Querulant fängt schon zum Diskutieren an!', '[{"kategorie": "wörtlich", "text": "\"Noch ist kein Stich gespielt, und der Querulant fängt schon an zu diskutieren!\"  2. \"Bevor überhaupt eine Karte liegt, beginnt der Unruhestifter schon zu meckern!\"  3. \"Noch ist nichts gespielt, aber der Querulant macht schon eine Grundsatzdebatte daraus!\""}]'::jsonb, ''),
  ('hoi-de-quetschn-ausse-und-schbueue-endlich-auf-sunst-wiad-des-do-a-trauafeia', 'Hoi de Quetschn ausse und schbüü endlich auf - sunst wiad des do a Trauafeia!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Hol die Quetschen raus und spiel endlich auf - sonst wird das da ''ne Trauerfeier!', '[{"kategorie": "wörtlich", "text": "\"Hol die Ziehharmonika raus und leg endlich los - sonst wird das hier ''ne Trauerfeier!\"  2. \"Pack aus dein Akkordeon und spiel endlich auf - sonst stirbt hier noch die Stimmung!\"  3. \"Hol raus dein Maurerklavier und mach Musik - sonst kippt die Stimmung endgültig ins Grab!\""}]'::jsonb, ''),
  ('in-dera-quetschn-kaunnst-ned-umfoin-dafia-is-aafoch-ka-plotz', 'In dera Quetschn kaunnst ned umfoin - dafia is aafoch ka Plotz!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'In dieser Quetschen kannst du nicht umfallen - dafür ist einfach kein Platz!', '[{"kategorie": "wörtlich", "text": "\"In diesem Stehbeisl kannst du nicht umfallen - dafür ist schlicht kein Platz!\"  2. \"In dieser kleinen Schankstube kannst du nicht umfallen - da drin trägt dich nicht dein Gleichgewicht, sondern die drängelnde Masse!\"  3. \"Diese Kaschemme ist immer gerammelt voll - die ist sogar zu eng zum Fallen!\""}]'::jsonb, ''),
  ('i-schupf-mei-quetschn-gaunz-allaanich', 'I schupf mei Quetschn gaunz allaanich!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Ich schupfe meine Quetschen ganz alleine!', '[{"kategorie": "wörtlich", "text": "\"Ich schmeiß den Laden ganz alleine!\"  2. \"Ich betreibe meinen Miniladen im Alleingang!\"  3. \"Ich halt den Betrieb ganz alleine am Laufen!\""}]'::jsonb, ''),
  ('quetschnziaga-schbueue-auf-gib-eam-schdimmung', 'Quetschnziaga, schbüü auf - gib eam, Schdimmung!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Quetschenzieher, spiel auf - gib ihm, Stimmung!', '[{"kategorie": "wörtlich", "text": "\"Harmonikaspieler, leg los! - Hau dich in die Tasten - Stimmung!\"  2. \"Quetschenspieler, würg den Balg und leg los - wir wollen Stimmung!\"  3. \"Harmonikaspieler, gib Gas und drück drauf, dass die Bänke wackeln!\""}]'::jsonb, ''),
  ('bei-da-poika-hoit-da-quetschnschbueuela-in-ritmus-zsaumm-ea-fiad-und-da-rest-foigd-eam', 'Bei da Poika hoit da Quetschnschbüüla in Ritmus zsaumm - ea fiad, und da Rest foigd eam!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Bei der Polka hält der Quetschenspieler den Rhythmus zusammen - er führt, und der Rest folgt ihm!', '[{"kategorie": "wörtlich", "text": "\"Der Harmonikaspieler ist bei der Polka der Motor – er gibt den Takt vor, alle anderen folgen ihm!\"  2. \"Bei der Polka zieht der Quetschenspieler vorneweg, der Rest hängt sich im Takt an ihm an!\"  3. \"Bei der Polka gibt der Quetschenzieher den Schritt vor - er hält alles auf Spur, und der Rest folgt ihm!\""}]'::jsonb, ''),
  ('quatsch-ma-moi-olle-mitanaunda', 'Quatsch ma moi olle mitanaunda!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Quatschen wir mal alle miteinander!', '[{"kategorie": "wörtlich", "text": "\"Lasst uns doch mal alle ganz ungezwungen miteinander reden!\"  2. \"Ich schlage vor, wir tauschen uns mal ganz ungezwungen miteinander aus!\"  3. \"Lasst uns einfach zusammensitzen und das Ganze miteinander ausreden!\""}]'::jsonb, ''),
  ('wos-du-do-quatschsd-intaressiad-mi-an-feichtn-schaas', 'Wos du do quatschsd, intaressiad mi an feichtn Schaas!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Was du da quatschst, interessiert mich einen feuchten Schas!', '[{"kategorie": "wörtlich", "text": "\"Was du da quasselst, interessiert mich einen feuchten Dreck!\"  2. \"Was du da von dir gibst, geht mir am Allerwertesten vorbei!\"  3. \"Was du da leberst, geht mir links rein und rechts raus!\""}]'::jsonb, ''),
  ('wos-do-in-da-kistn-liigd-is-ka-obst-mea-des-is-a-brauna-quatsch-volla-maadn', 'Wos do in da Kistn liigd, is ka Obst mea - des is a brauna Quatsch volla Maadn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Was da in der Kiste liegt, ist kein Obst mehr - das ist ein brauner Quatsch voller Maden!', '[{"kategorie": "wörtlich", "text": "\"Was da in der Kiste liegt, ist kein Obst mehr – das ist ein fauliger Früchtebrei voller Maden!\"  2. \"Das da in der Kiste ist kein Obst mehr - das ist nur noch ein brauner Matsch aus faulen Früchten!\"  3. \"Was da in der Kiste liegt, ist kein Obst mehr - das ist eine stinkende Fruchtpampe, die sich außerdem auch schon bewegt!\""}]'::jsonb, ''),
  ('wos-du-do-dazoeoesd-is-kompletta-quatsch-so-reed-nua-aana-dea-ka-aunung-hod', 'Wos du do dazöösd, is kompletta Quatsch - so reed nua aana, dea ka Aunung hod!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Was du da erzählst, ist kompletter Quatsch - so redet nur einer, der keine Ahnung hat!', '[{"kategorie": "wörtlich", "text": "\"Was du da sagst, ist reiner Unsinn - so redet nur einer, der keine Ahnung hat!\"  2. \"Was du da von dir gibst, ist kompletter Käse - das zeugt von völliger Ahnungslosigkeit!\"  3. \"Was du da quatscht, ist völliger Stuss – man merkt, dass du dich nicht auskennst!\""}]'::jsonb, ''),
  ('olle-mitanaunda', 'Olle mitanaunda!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Alle miteinander!', '[{"kategorie": "wörtlich", "text": "\"Alle zusammen!\"  2. \"Auf geht''s, alle gemeinsam!\"  3. \"Los, jetzt alle zusammen!\""}]'::jsonb, ''),
  ('estahaasi-schnittn', 'Estahaasi-Schnittn', 'die', '', '', 'Wiener Küche & Gaumenfreuden', 'Esterházy-Schnitte', '[{"kategorie": "wörtlich", "text": "\"Esterhazy-Schnitte\" (Determinativkompositum aus \"Esterhazy\"=\"Adelsgeschlecht Esterházy\" [führende ungarisch-österreichische Fürstenfamilie, prägend für Politik, Kultur und Musik der Habsburgermonarchie] und \"Schnitte\"=\"Torte in Schnittenform\")"}, {"kategorie": "Kulinarik", "text": "\"Esterházy-Schnitte\" (feines Schichtgebäck aus mehreren dünnen Nuss-Baiser-Böden [meist mit Haselnüssen oder Mandeln], die mit einer Butter- oder Vanillecreme gefüllt sind. Die Oberseite ist typisch mit einer weißen Fondant- oder Zuckerglasur überzogen, die mit einem braunen Schokoladenmuster [Spinnennetz- oder Wellenzeichnung] verziert wird), \"klassisches Gebäck der österreichisch-ungarischen Konditorei\", \"ungarische Nusscremeschnitte\""}]'::jsonb, 'Hau de Estahaasi-Schnittn untad Tuatnglockn, sunst trickans uns wegga!'),
  ('hau-de-estahaasi-schnittn-untad-tuatnglockn-sunst-trickans-uns-wegga', 'Hau de Estahaasi-Schnittn untad Tuatnglockn, sunst trickans uns wegga!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Hau die Esterházy-Schnitten unter die Tortenglocke, sonst trocknen sie uns weg!', '[{"kategorie": "wörtlich", "text": "\"Pack die Esterházy-Schnitten unter die Tortenglocke, sonst werden sie staubtrocken!\"  2. \"Deck die Esterházy-Schnitten mit der Tortenhaube ab, damit sie nicht austrocknen!\"  3. \"Stell die Esterházy-Schnitten unter den Tortensturz - sonst werden sie trocken wie Zwieback!\""}]'::jsonb, ''),
  ('den-lack-kaumma-jo-nimma-saufn-bring-ma-a-frischs-bia', 'Den Lack kaumma jo nimma saufn! Bring ma a frischs Bia!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Den Lack kann man ja nicht mehr saufen! Bring mir ein frisches Bier!', '[{"kategorie": "wörtlich", "text": "\"Dieses abgestandene Bier kann man ja nicht mehr trinken! Bring mir ein frisches!\"  2. \"So einen Lack säuft ja kein Mensch – bring mir ein frisches Bier!\"  3. \"Dieses schale Bier hat ja keine Kohlensäure mehr - zapf mir ein frisches!\""}]'::jsonb, ''),
  ('host-lack-gsoffn', 'Host Lack gsoffn?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Hast du Lack gesoffen?', '[{"kategorie": "wörtlich", "text": "\"Hast du sie noch alle?\"  2. \"Bist du bescheuert?\"  3. \"Tickst du noch richtig?\"  4. \"Bist [[hiinnich]] in da Marüün?\""}]'::jsonb, ''),
  ('de-sendung-mochd-aus-oeoelaend-a-schbektakl-und-vakummd-damit-zu-an-reinan-sozialporno', 'De Sendung mochd aus Ööländ a Schbektakl und vakummd damit zu an reinan Sozialporno!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Die Sendung macht aus Elend ein Spektakel und verkommt damit zu einem reinen Sozialporno!', '[{"kategorie": "wörtlich", "text": "\"Die Show präsentiert das Elend als Attraktion und reduziert sich damit zu einem reinen Sozialporno!\"  2. \"Die zerren Elend vor die Kamera und nennen das Fernsehen – für mich ist das reiner Sozialporno!\"  3. \"Die Sendung macht Quote mit fremdem Elend - letztlich ist das reiner Sozialporno!\""}]'::jsonb, ''),
  ('fett-wiara-radiira', 'fett wiara Radiira', '', '', '', 'Echte Wiener Schmähperlen', 'fett wie ein Radierer', '[{"kategorie": "wörtlich", "text": "\"fett wie ein Radiergummi\" (Die Redewendung rührt daher, dass Radiergummis durch die Zugabe von Unschlitt früher sehr fettreich waren)"}, {"kategorie": "", "text": "\"voll bis oben hin\""}, {"kategorie": "", "text": "\"besoffen bis unter die Haarspitzen\""}, {"kategorie": "", "text": "[[fett]] wie eine Haubitzen"}, {"kategorie": "", "text": "[[fett]] wie ein Hydrant"}]'::jsonb, 'Noochn Festl woar I fett wiara Radiira - I hob ned amoi mea mei Raadl gfundn!'),
  ('noochn-festl-woar-i-fett-wiara-radiira-i-hob-ned-amoi-mea-mei-raadl-gfundn', 'Noochn Festl woar I fett wiara Radiira - I hob ned amoi mea mei Raadl gfundn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Nach dem Festl war ich fett wie ein Radierer - ich hab nicht einmal mehr mein Radl gefunden!', '[{"kategorie": "wörtlich", "text": "\"Nach der Feier war ich voll bis oben hin - ich hab nicht mal mehr mein Fahrrad gefunden!\"  2. \"Ich war nach der Feier fett wie ''ne Strandhaubitze - nicht mal mein Fahrrad hab ich gefunden!\"  3. \"Nach dem Fest war ich besoffen bis unter die Haarspitzen - mein Fahrrad hab ich gesucht wie blöd und nicht gefunden!\""}]'::jsonb, 'fett wiara Radiira'),
  ('an-radetzky-mochn', 'an Radetzky mochn', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'einen Radetzky machen', '[{"kategorie": "wörtlich, Schülerjargon", "text": "\"einen Schreibfehler, etc. ausradieren\""}, {"kategorie": "", "text": "\"etwas mit dem Radiergummi ausradieren\""}, {"kategorie": "", "text": "\"einen Radetzky über etwas machen\" („Radetzky“ als Bezeichnung für den Radierer entstand aus der Popularität des österreichischen Feldmarschalls Josef Wenzel Graf Radetzky [1766-1858], sowie der Lautähnlichkeit dessen Familiennamens zu „radieren“ und der ironischen Übertragung militärischer „Beseitigung“ auf Schreibfehler)"}]'::jsonb, 'Moch an Radetzky driiwa!'),
  ('moch-an-radetzky-driiwa', 'Moch an Radetzky driiwa!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Mach einen Radetzky drüber!', '[{"kategorie": "wörtlich", "text": "\"Geh mit dem Radierer drüber!\"  2. \"Radier das weg!\"  3. \"Das muss weg - radier drüber!\""}]'::jsonb, 'an Radetzky mochn'),
  ('radetzky-schau-owe', 'Radetzky schau owe!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Radetzky schau runter!', '[{"kategorie": "wörtlich, scherzhaft für", "text": "\"Verdammter Schreibfehler!\"  2. \"Wieder muss ich was ausradieren!\"  3. \"Verdammt, schon wieder muss ich mit dem Radierer drübergehen!\"  (Scherzspruch, wenn man einen Schreibfehler macht und zum Radierer greifen muss - „Radetzky“ als Bezeichnung für den Radierer entstand aus der Popularität des österreichischen Feldmarschalls Josef Wenzel Graf Radetzky [1766-1858], sowie der Lautähnlichkeit dessen Familiennamens zu „radieren“ und der ironischen Übertragung militärischer „Beseitigung“ auf Schreibfehler)"}]'::jsonb, ''),
  ('wem-in-radetzkymarsch-bloosn', 'wem in Radetzkymarsch bloosn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem den Radetzkymarsch blasen', '[{"kategorie": "wörtlich,", "text": "\"jemandem die Meinung sagen\" (nach dem bekannten Musikstück von Johann Strauß Vater [[[Radetzkymarsch]]], welches er dem österreichischen Feldmarschall Josef Wenzel Graf Radetzky [1766-1858] gewidmet hat und welches bis heute alljährlich als Schlussnummer beim  weltberühmten [[Neujahrskonzert]] der Wiener Philharmoniker aufgeführt wird)"}, {"kategorie": "", "text": "\"jemanden zur Sau machen\""}, {"kategorie": "", "text": "\"jemandem Feuer unterm Hintern machen\""}, {"kategorie": "", "text": "\"jemandem den Marsch blasen\""}]'::jsonb, 'Seitn Schaani sein Fremdpuudara bloosd eam sei Oide nua mea in Radetzkymarsch!'),
  ('seitn-schaani-sein-fremdpuudara-bloosd-eam-sei-oide-nua-mea-in-radetzkymarsch', 'Seitn Schaani sein Fremdpuudara bloosd eam sei Oide nua mea in Radetzkymarsch!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Seit dem Fremdpuderer vom Schani bläst ihm seine Alte nur noch den Radetzkymarsch!', '[{"kategorie": "wörtlich", "text": "\"Seit Johanns Seitensprung bläst ihm seine Alte nur noch den Radetzkymarsch!\"  2. \"Seit dem Seitensprung vom Schani kriegt er daheim nur noch den Radetzkymarsch geblasen!\"  3. \"Seit der Schani fremdgepudert hat, bläst ihm eine Alte nur noch den Radetzkymarsch!\""}]'::jsonb, 'wem in Radetzkymarsch bloosn'),
  ('wos-min-radetzkymarsch-vawechsln', 'wos min Radetzkymarsch vawechsln', '', '', '', 'Wiener Sprüche, die sitzen!', 'etwas mit dem Radetzkymarsch verwechseln', '[{"kategorie": "wörtlich", "text": "\"Kraut und Rüben verwechseln\""}, {"kategorie": "", "text": "\"Äpfel und Birnen verwechseln\""}, {"kategorie": "", "text": "\"Dinge verwechseln, die nichts miteinander gemein haben\" (nach dem bekannten Musikstück von Johann Strauß Vater [[[Radetzkymarsch]]], welches er dem österreichischen Feldmarschall Josef Wenzel Graf Radetzky [1766-1858] gewidmet hat und welches bis heute alljährlich als Schlussnummer beim  weltberühmten [[Neujahrskonzert]] der Wiener Philharmoniker aufgeführt wird)"}, {"kategorie": "", "text": "\"alles durcheinanderbringen\""}]'::jsonb, 'So wia du argumentiasd, vawechslsd ma ollas min Radetzkymarsch!'),
  ('so-wia-du-argumentiasd-vawechslsd-ma-ollas-min-radetzkymarsch', 'So wia du argumentiasd, vawechslsd ma ollas min Radetzkymarsch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So wie du argumentierst, verwechselst du mir alles mit dem Radetzkymarsch!', '[{"kategorie": "wörtlich", "text": "\"So wie du argumentierst, schmeißt du Kraut und Rüben durcheinander!\"  2. \"So wie du argumentierst, vergleichst du Äpfel mit Birnen!\"  3. \"Mit der Argumentation liegst du völlig daneben - du wirfst ja alles wild durcheinander!\""}]'::jsonb, 'wos min Radetzkymarsch vawechsln'),
  ('mit-hoeoem-brueuen-und-karbonrauman-fueuel-i-mi-ois-raadla-wiara-profi', 'Mit Hööm, Brüün und Karbonrauman füül I mi ois Raadla wiara Profi!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Mit Helm, Brille und Carbonrahmen fühl'' ich mich als Radler wie ein Profi!', '[{"kategorie": "wörtlich", "text": "\"Helm und Brille auf dem Kopf, Carbonrad unterm Hintern - da fühlst du dich als Radfahrer wie ein Profi!\"  2. \"Mit meinem Helm, der Brille auf der Nase und dem Carbonrahmen unterm Hintern fühle ich mich, als gehörte ich als Radler zur Profiliga!\"  3. \"Mit Helm, Sportbrille und Carbonrad fühle ich mich nicht als gewöhnlicher Pedalritter, sondern fast schon wie ein Radrennfahrer!\""}]'::jsonb, ''),
  ('heit-bleib-i-beim-raadla-i-wueue-jo-muang-no-wissen-wiar-i-haass', 'Heit bleib I beim Raadla - I wüü jo muang no wissen, wiar I haass!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Heut bleib ich beim Radler - ich will ja morgen noch wissen, wie ich heiße!', '[{"kategorie": "wörtlich", "text": "\"Ich bleib heut beim Radler, damit ich morgen noch weiß, wie ich heiß!\"  2. \"Heute kein Vollrausch, ich bleib beim Radler!\"  3. \"Ich halt mich heut zurück - statt Bier trink ich heut nur Radler, sonst bin ich morgen ein Wrack!\""}]'::jsonb, ''),
  ('do-is-finsta-wiar-in-an-roobnoasch', 'Do is finsta wiar in an Roobnoasch!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Da ist es finster wie in einem Rabenarsch!', '[{"kategorie": "wörtlich", "text": "\"Da ist es stockdunkel wie im Arsch eines Raben!\"  2. [[Da ist es finster wie in Teufels Arschloch!]]  3. à\"Da ist es finster wie in einem Bärenarsch!"}]'::jsonb, ''),
  ('auf-a-raandl', 'auf a Raandl', '', '', '', 'Wiener Sprüche, die sitzen!', 'auf ein Randl', '[{"kategorie": "wörtlich", "text": "\"auf einen kurzen Moment\""}, {"kategorie": "", "text": "\"auf einen Sprung\""}, {"kategorie": "", "text": "\"auf ein Minütchen\""}]'::jsonb, ''),
  ('auf-a-raandal', 'auf a Raandal', '', '', '', 'Wiener Sprüche, die sitzen!', 'auf ein Randerl', '[{"kategorie": "wörtlich", "text": "\"auf einen kurzen Moment\""}, {"kategorie": "", "text": "\"auf einen Sprung\""}, {"kategorie": "", "text": "\"auf ein Minütchen\""}]'::jsonb, ''),
  ('kumm-auf-a-raandal-vuabei', 'Kumm auf a Raandal vuabei!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Komm auf ein Randerl vorbei!', '[{"kategorie": "wörtlich", "text": "\"Komm nur auf ein Minütchen vorbei!\"  2. \"Schau nur ganz kurz mal vorbei!\"  3. \"Komm doch nur auf einen Sprung vorbei!\""}]'::jsonb, 'auf a Raandal'),
  ('schau-nua-auf-a-raandl-eine', 'Schau nua auf a Raandl eine!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Schau nur auf ein Randl ein!', '[{"kategorie": "wörtlich", "text": "\"Schau für einen Augenblick rein!\"  2. \"Schau nur ganz kurz vorbei!\"  3. \"Komm nur auf einen Sprung vorbei!\""}]'::jsonb, 'auf a Raandl'),
  ('si-an-raund-neema', 'si an Raund neema', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich einen Rand nehmen', '[{"kategorie": "wörtlich", "text": "\"sich einen Ruck geben\""}, {"kategorie": "", "text": "\"einen Anlauf nehmen\""}, {"kategorie": "", "text": "\"sich ein Herz nehmen\""}, {"kategorie": "", "text": "\"allen Mut zusammennehmen\""}]'::jsonb, 'Nimm da an Raund und soog ia de Woaheit!'),
  ('nimm-da-an-raund-und-soog-ia-de-woaheit', 'Nimm da an Raund und soog ia de Woaheit!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nimm dir ''nen Rand und sag ihr die Wahrheit!', '[{"kategorie": "wörtlich", "text": "\"Nimm deinen Mut zusammen und sag ihr die Wahrheit!\"  2. \"Fass dir ein Herz und sag ihr endlich die Wahrheit!\"  3. \"Gib dir einen Ruck und sag ihr ehrlich, was Sache ist!\""}]'::jsonb, 'si an Raund neema'),
  ('kumm-nua-auf-an-raund-vuabei-muassd-jo-ned-laung-bleibm', 'Kumm nua auf an Raund vuabei - muassd jo ned laung bleibm!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Komm nur auf einen Rand vorbei - musst ja nicht lang bleiben!', '[{"kategorie": "wörtlich", "text": "\"Schau nur auf einen Moment vorbei - du musst ja nicht lange bleiben!\"  2. \"Komm doch kurz vorbei – nix Langes!\"  3. \"Schau auf einen Sprung vorbei - nur kurz reinschauen, mehr nicht!\""}]'::jsonb, ''),
  ('an-raund-mochn', 'an Raund mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Rand machen', '[{"kategorie": "wörtlich", "text": "\"eine Gaudi machen\""}, {"kategorie": "", "text": "\"Schabernack treiben\""}, {"kategorie": "", "text": "\"eine [[Hetz]] machen\""}]'::jsonb, 'Aum Festl weans wiida an muadstrumm Raund mochn!'),
  ('aum-festl-weans-wiida-an-muadstrumm-raund-mochn', 'Aum Festl weans wiida an muadstrumm Raund mochn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Am Fest werden sie wieder einen mordstrumm Rand machen!', '[{"kategorie": "wörtlich", "text": "\"Beim Fest werden sie wieder eine Riesengaudi machen!\"  2. \"Auf dem Fest werden sie wieder eine Riesenhetz veranstalten!\"  3. \"Beim Fest werden sie wieder ordentlich Schabernack treiben!\""}]'::jsonb, 'an Raund mochn'),
  ('nua-an-groossn-raund-haum-is-ned-ollas', 'Nua an groossn Raund haum is ned ollas!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Nur einen großen Rand haben ist nicht alles!', '[{"kategorie": "wörtlich", "text": "\"Bloß eine große Klappe zu haben, ist nicht alles!\""}, {"kategorie": "", "text": "\"Nur große Töne zu spucken, genügt nicht!\"  3. \"Nur das Maul weit aufzureißen, ist nicht genug!\""}]'::jsonb, ''),
  ('do-hoda-in-raund-wiida-z-voi-gnumma', 'Do hoda in Raund wiida z''voi gnumma!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da hat er den Rand wieder zu voll genommen!', '[{"kategorie": "wörtlich", "text": "\"Da hat er den Mund wieder zu voll genommen!\"  2. \"Da hat er die Klappe wieder zu weit aufgerissen!\"  3. \"Da hat er wieder zu große Töne gespuckt!\""}]'::jsonb, ''),
  ('dea-muass-heit-a-raundae-haum-so-wiara-si-de-gatschwoeoen-aufgfoeoend-hod', 'Dea muass heit a Raundä haum - so wiara si de Gatschwöön aufgföönd hod!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der muss heute ein Rendezvous haben - so wie er sich seine Gatschwelle aufgeföhnt hat!', '[{"kategorie": "wörtlich", "text": "\"Der hat heute wohl ein Date – so wie er sich seine Schmalzlocke aufgeföhnt hat!\"  2. \"Schau, wie sich der seine Gatschwelle eingegelt hat - der hat heut fix ein Date!\"  3. \"Der muss heute eine Verabredung haben - so geschniegelt wie der ist!\""}]'::jsonb, ''),
  ('a-raundi-haum', 'a Raundi haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein Rendez haben', '[{"kategorie": "wörtlich", "text": "\"ein Rendezvous haben\""}, {"kategorie": "", "text": "\"eine Verabredung haben\""}, {"kategorie": "", "text": "\"ein Date haben\""}]'::jsonb, 'Waunn dea a Raundi hod, liigt sei Gatschwöön wia betoniad!'),
  ('waunn-dea-a-raundi-hod-liigt-sei-gatschwoeoen-wia-betoniad', 'Waunn dea a Raundi hod, liigt sei Gatschwöön wia betoniad!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Wenn der ein Rendezvous hat, liegt seine Gatschwelle wie betoniert!', '[{"kategorie": "wörtlich", "text": "\"Wenn der ein Date hat, sitzt seine Schmachtlocke wie festgeschraubt!\"  2. \"Wenn der eine Verabredung hat, wackelt seine Elvis-Locke keinen Millimeter!\"  3. \"Wenn der ein Blind Date hat, sitzt seine Gatschwelle wie angeklebt!\""}]'::jsonb, 'a Raundi haum'),
  ('si-an-aunraund-neema', 'si an Aunraund neema', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich einen Anrand nehmen', '[{"kategorie": "wörtlich", "text": "\"sich einen Anlauf nehmen\""}, {"kategorie": "", "text": "\"sich einen Ruck geben\""}, {"kategorie": "", "text": "\"sich ein Herz nehmen\""}, {"kategorie": "", "text": "\"allen Mut zusammennehmen\""}]'::jsonb, 'Zeaschd hoda umadumdrucksd, owa daunn hoda si an Aunraund gnumma und Tacheles greedt!'),
  ('zeaschd-hoda-umadumdrucksd-owa-daunn-hoda-si-an-aunraund-gnumma-und-tacheles-greedt', 'Zeaschd hoda umadumdrucksd, owa daunn hoda si an Aunraund gnumma und Tacheles greedt!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Zuerst hat er herumgedruckst, aber dann hat er sich einen Anrand genommen und Tacheles geredet!', '[{"kategorie": "wörtlich", "text": "\"Zuerst hat er herumgedruckst, aber dann hat er sich einen Ruck gegeben und Tacheles geredet!\"  2. \"Anfangs zögerte er noch, aber dann fasste er sich ein Herz und sprach Klartext!\"  3. \"Zuerst hat er noch rumgeeiert, aber dann hat er allen Mut zusammengenommen und offen ausgesprochen, was Sache ist!\""}]'::jsonb, 'si an Aunraund neema'),
  ('aum-kiatoog-san-de-randlbeem-duachd-vuaschdodt-zoong-und-haum-eanare-gloospealaen-und-bandln-faeubootn', 'Aum Kiatoog san de Randlbeem duachd Vuaschdodt zoong und haum eanare Gloospealän und Bandln fäubootn!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Am Kirtag sind die Randlböhm durch die Vorstadt gezogen und haben ihre Glasperlen und Bänder feilgeboten!', '[{"kategorie": "wörtlich", "text": "\"Zur Kirchtagszeit zogen die böhmischen Wanderhändler wieder durch die Vorstadt und boten ihre Glasperlen und Bänder feil!\"  2. \"Am Kirchweihfest durchstreiften böhmische Hausierer die Vorstadt mit Glaswaren und Bändern!\"  3. \"Mit dem Kirtag kamen die böhmischen Händler, zogen durch die Gassen und boten ihre bunten Waren feil!\""}]'::jsonb, ''),
  ('mit-ana-schwean-kraxn-aum-buugl-san-de-kraxnmandln-zu-weinochntn-duach-de-vuaschdodtgossn-gwaundad', 'Mit ana schwean Kraxn aum Buugl san de Kraxnmandln zu Weinochntn duach de Vuaschdodtgossn gwaundad!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Mit einer schweren Kraxe auf dem Buckel sind die Kraxenmandln zu Weihnachten durch die Vorstadtgassen gewandert!', '[{"kategorie": "wörtlich", "text": "\"Mit ''nem schweren Tragekorb auf dem Rücken wanderten die hausierenden Händler zu Weihnachten durch die Vorstadtgassen von Wien!\"  2. \"Mit schweren Tragkörben auf dem Rücken zogen die Hausierer einst zur Weihnachtszeit durch die Vorstadtgassen Wiens!\"  3. \"Mit schwerem Korbwerk auf dem Rücken zogen die Hausierer zur Weihnachtszeit durch die Wiener Vorstadt!\""}]'::jsonb, ''),
  ('noochn-ookochn-setzd-si-auf-da-mueuech-a-dicka-raam-oo', 'Noochn Ookochn setzd si auf da Müüch a dicka Raam oo!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Nach dem Abkochen setzt sich auf der Milch ein dicker Rahm ab!', '[{"kategorie": "wörtlich", "text": "\"Nach dem Erhitzen bildet sich auf der Milch eine dicke Rahmschicht!\"  2. \"Beim Abkühlen legt sich ein kräftiger Rahm auf die Milch!\"  3. \"Nach dem Abkochen sammelt sich oben aufder Milch eine dicke Fettschicht!\""}]'::jsonb, ''),
  ('de-suppn-kriagd-duachn-raam-ia-mueuede-runde-nootn', 'De Suppn kriagd duachn Raam ia müüde, runde Nootn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Die Suppe kriegt durch den Rahm ihre milde, runde Note!', '[{"kategorie": "wörtlich", "text": "\"Der Rahm verleiht der Suppe eine milde, ausgewogene Note!\"  2. \"Durch den Rahm wird die Suppe sanft und harmonisch im Geschmack!\"  3. \"Ein Löffel Rahm gibt der Suppe ihre feine Milde und Fülle!\""}]'::jsonb, ''),
  ('wos-hostn-do-fiara-remasuuri-augricht', 'Wos hostn do fiara Remasuuri augricht?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Was hast du denn da für eine Remasuri angerichtet?', '[{"kategorie": "wörtlich", "text": "\"Was hast du denn da für eine Unordnung angerichtet?\"  2. \"Was hast du denn da für ein Chaos verursacht?\"  3. \"Was für ein Durcheinander hast du denn da fabriziert?\""}]'::jsonb, ''),
  ('wos-isn-des-do-fiara-ramasuuri-do-glaubsd-jo-de-sau-is-auslossn', 'Wos isn des do fiara Ramasuuri? - Do glaubsd jo, de Sau is auslossn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Was ist denn das da für ''ne Ramasuri? - Da glaubst ja, die Sau ist ausgelassen!', '[{"kategorie": "wörtlich", "text": "\"Was ist das denn das da für ein hektischer Trubel? - Da geht’s ja drunter und drüber!\"  2. \"Was ist denn das da für ein Wirbel? - Hier geht’s ja ab wie auf ''nem Jahrmarkt!\"  3. \"Was für ein Rummel – man meint, die Welt steht hier Kopf!\""}]'::jsonb, ''),
  ('waunn-mei-oida-nua-fuenf-minuutn-allaa-in-da-kuchl-is-hauma-a-ramasuuri-wia-noch-aana-explosion', 'Waunn mei Oida nua fünf Minuutn allaa in da Kuchl is, hauma a Ramasuuri wia noch aana Explosion!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Wenn mein Alter nur fünf Minuten allein in der Küche ist, haben wir ''ne Ramasuri wie nach ''ner Explosion!', '[{"kategorie": "wörtlich", "text": "\"Wenn mein Mann nur fünf Minuten allein in der Küche ist, herrscht ein Durcheinander wie nach ''ner Explosion!\"  2. \"Lässt man meinen Alten nur fünf Minuten allein in der Küche werken, sieht’s aus wie nach einem Bombenalarm!\"  3. \"Wenn mein Mann nur fünf Minuten unbeaufsichtigt in der Küche ist, herrscht dort anschließend totales Chaos!\""}]'::jsonb, ''),
  ('suewoeoesta-oone-remmidemmi-is-wiara-sekt-oone-koaknknoin', 'Süwöösta oone Remmidemmi is wiara Sekt oone Koaknknoin!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Silvester ohne Remmidemmi ist wie ein Sekt ohne Korkenknallen!', '[{"kategorie": "wörtlich", "text": "\"Silvester ohne Rambazamba ist wie ein Feuerwerk ohne Zündung!\"  2. \"Silvester ohne Remasuri ist wie ein Schmäh ohne Pointe!\"  3. \"Silvester ohne Trubel und Tamtam ist wie ''ne Party ohne Gäste!\""}]'::jsonb, ''),
  ('in-da-afrikaanischn-und-asiaatischn-kultua-hods-tamtam-a-rituelle-bedeitung-ghobd-es-woa-ned-nua-a-musikinstrument-sondan-aar-a-zeichn-und-signaal', 'In da afrikaanischn und asiaatischn Kultua hods Tamtam a rituelle Bedeitung ghobd: Es woa ned nua a Musikinstrument, sondan aar a Zeichn und Signaal!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'In der afrikanischen und der asiatischen Kultur hat das Tamtam eine rituelle Bedeutung gehabt: Es war nicht nur ein Musikinstrument, sondern auch Zeichen und Signal!', '[{"kategorie": "wörtlich", "text": "\"In afrikanischen und asiatischen Kulturen besaß das Tamtam rituelle Funktion: Es diente nicht allein musikalischen Zwecken, sondern auch der Signalgebung!\"  2. \"Das Tamtam - d.h. die Handtrommel in Afrika und der Gong in Asien - war nicht nur ein Musikinstrument; es war auch Teil ritueller Praxis und zugleich ein Mittel der akustischen Verständigung!\"  3. \"In Afrika und Asien war das Tamtam mehr als nur Musik - es diente als eine Art Signal und hatte zugleich auch rituelle Bedeutung!\""}]'::jsonb, ''),
  ('mochds-kaa-tamtam', 'Mochds kaa Tamtam!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Macht kein Tamtam!', '[{"kategorie": "wörtlich", "text": "\"Macht kein Theater!\"  2. \"Macht nicht so einen Wirbel!\"  3. \"Nur keine Aufregung!\"  4. \"Macht nicht so ''nen Zirkus!\""}]'::jsonb, ''),
  ('weeng-dem-leachalschaas-wiad-vueue-z-vueue-tamtam-gmochd', 'Weeng dem Leachalschaas wiad vüü z''vüü Tamtam gmochd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wegen diesem Lercherlschas wird viel zu viel Tamtam gemacht!', '[{"kategorie": "wörtlich", "text": "\"Wegen dieser Lappalie wird ein viel zu großer Wirbel gemacht!\"  2. \"Wegen dieser Bagatelle wird ein viel zu großer Rummel veranstaltet!\"  3. \"Wegen so einem Schmarrn einen derartigen Riesenzirkus zu veranstalten, geht weit übers Ziel hinaus!\""}]'::jsonb, ''),
  ('des-woa-kaa-festl-mea-des-woara-tamtam-mit-beifaung', 'Des woa kaa Festl mea - des woara Tamtam mit Beifaung!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das war kein Fest mehr - das war ein Tamtam mit Beifang!', '[{"kategorie": "wörtlich", "text": "\"Das war kein Fest mehr, das war Rummel mit Kollateralschaden!\"  2. \"Das ging weit über ein Fest hinaus – das war eine Remasuri inklusive Nachwehen!\"  3. \"Das hatte mit Feiern nichts mehr zu tun - das war ein Remmidemmi mit Vollgas, null Kontrolle und anschließendem [[Haarspitzenkatarrh]]!\""}]'::jsonb, ''),
  ('in-da-hittn-woa-so-a-halligalli-dass-sogoa-de-tiarlschdeeha-aufgeebm-haum-miassn', 'In da Hittn woa so a Halligalli, dass sogoa de Tiarlschdeeha aufgeebm haum miassn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'In der Hütte war so ein Halligalli, dass sogar die Türsteher aufgeben haben müssen!', '[{"kategorie": "wörtlich", "text": "\"In der Bude ging so ein Rambazamba ab, dass selbst die Türsteher kapituliert haben!\"  2. \"Drinnen tobte so ein Halligalli, dass selbst die die Türsteher keinen Auftrag mehr hatten!\"  3. \"In der Disco herrschte ein derartiges Remmidemmi, dass selbst die Türsteher chancenlos waren!\""}]'::jsonb, ''),
  ('sei-raundschdaahummae-huast-schreit-und-read-und-weckt-ollas-auf-wos-uawaschln-hod', 'Sei Raundschdaahummä huast, schreit und read -und weckt ollas auf, wos Uawaschln hod!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Seine Randsteinhummel hustet, schreit und röhrt – und weckt alles auf, was Ohrwascheln hat!', '[{"kategorie": "wörtlich", "text": "\"Sein Bordsteinbrummer hustet, schreit und röhrt – und weckt alles auf, was Ohren hat!\"  2. \"Wenn der mit seinem Moped durch die Gasse pfeift, sitzt die ganze Nachbarschaft senkrecht im Bett!\"  3. \"Seine Randsteinhummel kreischt, ruckelt und heult - das reißt jedes Ohr in der Gasse aus dem Tiefschlaf!\""}]'::jsonb, ''),
  ('da-raundschdaa-bewegd-si-nii-gwinnd-owa-trotzdem-a-jeeds-duoeoe-mit-da-foeoeng', 'Da Raundschdaa bewegd si nii, gwinnd owa trotzdem a jeeds Duöö mit da Fööng!', '', '', '', 'Wiener Mechaniker-Slang', 'Der Randstein bewegt sich nie, gewinnt aber trotzdem jedes Duell gegen die Felge!', '[{"kategorie": "wörtlich", "text": "\"Der Bordstein bewegt keinen Zentimeter, gewinnt aber trotzdem jedes Duell gegen die Felge!\"  2. \"Der Randstein steht nur deppert da und macht trotzdem jede Felge fertig!\"  3. \"Unbeweglich steht der Randstein da, während die Felge wieder mal nachgibt!\""}]'::jsonb, ''),
  ('zeaschd-a-klaana-raundschdaaseawiira-zum-aufwaeaman-und-daunn-geeds-auns-auns-echte-kickn', 'Zeaschd a klaana Raundschdaaseawiira zum Aufwäaman - und daunn geeds auns auns echte Kickn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Zuerst ein kleiner Randsteinservierer zum Aufwärmen - und dann geht''s ans echte Kicken!', '[{"kategorie": "wörtlich", "text": "\"Erst ein kleiner Bordsteinkick zum Aufwärmen - und dann wird richtig Fußball gespielt!\"  2. \"Erst ein paar Randsteinservierer zum Reinkommen, dann wird richtig gekickt!\"  3. \"Erst kurz warmspielen am Bordstein und dann den Fußball richtig fliegen lassen!\""}]'::jsonb, ''),
  ('de-rapunzl-is-a-typischs-wintagemueuese-friara-hod-mas-direkt-vom-ocka-gsaummaed', 'De Rapunzl is a typischs Wintagemüüse - friara hod mas direkt vom Ocka gsaummäd!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Die Rapunzel ist ein typisches Wintergemüse - früher hat man''s direkt vom Acker gesammelt!', '[{"kategorie": "wörtlich", "text": "\"Die Rapunzel zählt zu den klassischen Wintergemüsen und wurde früher direkt auf dem Feld geerntet!\"  2. \"Rapunzel war früher ein echtes Wintergemüse – man ist einfach aufs Feld gegangen und hat sie gepflückt!\"  3. \"Die Rapunzel gehört zum Winter wie der Frost; früher hat man sie direkt vom Acker geholt!\""}]'::jsonb, ''),
  ('da-rapunzlsolood-wiad-bei-uns-mit-bianan-woiniss-und-an-senfdressing-seawiad', 'Da Rapunzlsolood wiad bei uns mit Bianan, Woiniss und an Senfdressing seawiad!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Der Rapunzelsalat wird bei uns mit Birnen, Walnüssen und einem Senfdressing serviert!', '[{"kategorie": "wörtlich", "text": "\"Bei uns serviert man Feldsalat mit Birnen, Walnüssen und Senfdressing!\"  2. \"Wir reichen den [[Vogerlsalat]] mit Birnen, Walnüssen und einem kräftigen Senfdressing!\"  3. \"Bei uns kommt der [[Bummerlsalat]] mit Birnen, Walnüssen und Senfsoße auf den Tisch!\""}]'::jsonb, ''),
  ('an-rappae-kriang', 'an Rappä kriang', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Rappel kriegen', '[{"kategorie": "wörtlich", "text": "\"einen Anfall kriegen\""}, {"kategorie": "", "text": "\"einen Ausraster haben\""}, {"kategorie": "", "text": "\"die Nerven verlieren\""}, {"kategorie": "", "text": "\"eine verrückte Anwandlung haben\""}]'::jsonb, 'Si kriagd a jeeds Moi an Rappä, waunn I voifett haamkumm - ois warads es easchde Moi!'),
  ('si-kriagd-a-jeeds-moi-an-rappae-waunn-i-voifett-haamkumm-ois-warads-es-easchde-moi', 'Si kriagd a jeeds Moi an Rappä, waunn I voifett haamkumm - ois warads es easchde Moi!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Sie kriegt jedes Mal einen Rappel, wenn ich vollfett heimkomme - als wär''s das erste Mal!', '[{"kategorie": "wörtlich", "text": "\"Sie kriegt jedes Mal einen Anfall, wenn ich total dicht nach Hause komme – als wär’s das erste Mal!\"  2. \"Sie hat jedes Mal einen Ausraster, wenn ich stockbetrunken heimkomme – als ob sie’s nicht kennen würde!\"  3. \"Sie kriegt jedes Mal verrückte Anwandlungen, wenn ich sternhagelvoll heimkomme – als wär’s neu für sie!\""}]'::jsonb, ''),
  ('i-hob-dem-rappaekopf-gsoogd-ea-soi-de-goschn-hoitn-owa-dea-head-nua-si-soeoewa', 'I hob dem Rappäkopf gsoogd, ea soi de Goschn hoitn - owa dea head nua si sööwa!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich hab dem Rappelkopf gesagt, er soll die Gosch''n halten - aber der hört nur sich selbst!', '[{"kategorie": "wörtlich", "text": "\"Ich hab dem Knallkopf gesagt, er soll die Klappe halten - aber der hört nur sich selbst!\"  2. \"Ich hab dem Wirrkopf gesagt, er soll ruhig sein – aber bei dem kommt nichts an!\"  3. \"Ich hab dem komischen Vogel gesagt, er soll endlich die Schnauze halten – aber der lebt in seiner eigenen Welt!\""}]'::jsonb, ''),
  ('bei-dem-rappaekopf-muassd-aufpassn-dea-is-glei-auf-hundad-waunns-ned-nooch-sein-schaeaedl-rennd', 'Bei dem Rappäkopf muassd aufpassn - dea is glei auf hundad, waunns ned nooch sein Schäädl rennd!', '', '', '', 'Wiener Gaunersprache', 'Bei dem Rappelkopf musst du aufpassen - der ist gleich auf hundert, wenn''s nicht nach seinem Schädel rennt!', '[{"kategorie": "wörtlich", "text": "\"Bei dem Hitzkopf musst du vorsichtig sein – der geht sofort hoch, wenn was gegen seinen Willen läuft!\"  2. \"Pass auf bei dem Heißsporn - der explodiert gleich, wenn’s nicht nach seiner Birne geht!\"  3. \"Nimm dich in Acht, bei dem Typen ist der Zünddraht kurz – der ist ruckzuck auf 180, wenn man ihm widerspricht!\""}]'::jsonb, ''),
  ('a-bissl-rappaekopfad-muassd-schoo-sei-waunnsd-so-an-saundhoosn-heiratsd', 'A bissl rappäkopfad muassd schoo sei, waunnsd so an Saundhoosn heiratsd!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ein bisschen rappelkopfert musst du schon sein, wenn du so ''nen Sandhasen heiratest!', '[{"kategorie": "wörtlich", "text": "\"Ein bisschen wirr im Kopf muss man schon sein, wenn man so eine untreue Tussi heiratet!\"  2. \"Wer so ein Flittchen heiratet, muss schief gewickelt sein!\"  3. \"Bei dem muss der Kompass ordentlich spinnen, wenn er so eine notorische Fremdgeherin heiratet!\""}]'::jsonb, ''),
  ('dea-is-a-bissl-rappaekopfad-den-soitast-ned-reizn', 'Dea is a bissl rappäkopfad - den soitast ned reizn!', '', '', '', 'Wiener Gaunersprache', 'Der ist ein bisschen rappelkopfert - den solltest du nicht reizen!', '[{"kategorie": "wörtlich", "text": "\"Der ist ein bisschen hitzköpfig - den reizt man besser nicht!\"  2. \"Der hat eine kurze Zündschnur - provozier'' ihn lieber nicht!\"  3. \"Der ist auf Krawall gebürstet - mit dem ist nicht zu spaßen!\""}]'::jsonb, ''),
  ('bei-dem-rappaeds', 'Bei dem rappäds!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bei dem rappelt''s!', '[{"kategorie": "wörtlich", "text": "\"Bei dem scheppert''s [im Kopf]!\"  2. \"Der spinnt!\"  3. \"Der hat seine fünf Sinne nicht beisammen!\"  4. \"Der ist voll neben der Spur!\""}]'::jsonb, ''),
  ('da-tood-is-a-wiina', 'Da Tood is a Wiina!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Der Tod ist ein Wiener!', '[{"kategorie": "wörtlich", "text": "\"Der Tod, das muss ein Wiener sein!\" (Titel eines Chansons von Georg Kreisler)"}, {"kategorie": "", "text": "\"Der Tod zeigt sich in seiner Art so, wie man es den Wienern nachsagt!\"  3. \"Der Tod repräsentiert die Eigenheiten, die man den Wienern zuschreibt!\""}]'::jsonb, ''),
  ('da-tood-des-muass-a-wiina-sei', 'Da Tood, des muass a Wiina sei!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Der Tod, das muss ein Wiener sein!', '[{"kategorie": "wörtlich", "text": "\"Der Tod verhält sich so, wie man es den Wienern zuschreibt!\" (Titel eines Chansons von Georg Kreisler)"}, {"kategorie": "", "text": "\"Der Tod zeigt sich in seiner Art so, wie man es den Wienern nachsagt!\"  3. \"Der Tod repräsentiert die Eigenheiten, die man den Wienern zuschreibt!\""}]'::jsonb, ''),
  ('aana-zeigd-de-ratata-und-schoo-hoidn-olle-de-goschn', 'Aana zeigd de Ratata - und schoo hoidn olle de Goschn!', '', '', '', 'Wiener Gaunersprache', 'Einer zeigt die Ratata - und schon halten alle die Goschen!', '[{"kategorie": "wörtlich", "text": "\"Einer zieht die Maschinenpistole - und schon hält jeder die Schnauze!\"  2. \"Kaum blitzt die Ratata, hält jeder die Fresse!\"  3. \"Zeigt einer die Maschinenknarre, ist schlagartig Sendepause!\""}]'::jsonb, ''),
  ('aana-mit-naamaschin-schdoeoed-kaane-froong-dea-beendet-gespraeche', 'Aana mit Naamaschin schdööd kaane Froong - dea beendet Gespräche!', '', '', '', 'Wiener Gaunersprache', 'Einer mit Nähmaschine stellt keine Fragen - der beendet Gespräche!', '[{"kategorie": "wörtlich", "text": "\"Einer mit Maschinenpistole stellt keine Fragen - der beendet Gespräche!\"  2. \"Wer mit einer Maschinenpistole auftaucht, will keine Antworten – der setzt den Schlusspunkt!\"  3. \"Eine MP ist kein Argument - sie ist das Ende der Debatte!\""}]'::jsonb, ''),
  ('in-da-karwochn-schweing-de-glockn-und-de-raatschn-iwanimmd-eanan-dienst', 'In da Karwochn schweing de Glockn, und de Raatschn iwanimmd eanan Dienst!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'In der Karwoche schweigen die Glocken, und die Ratsche übernimmt ihren Dienst!', '[{"kategorie": "wörtlich", "text": "\"Während der Karwoche verstummen die Glocken, stattdessen wird die Ratsche gedreht!\"  2. \"In der stillen Karwoche knattert die Ratsche dort, wo sonst die Glocken klingen!\"  3. \"Wenn die Glocken in der Karwoche ruhen, übernimmt die Ratsche den Rufdienst!\""}]'::jsonb, ''),
  ('kaum-passiad-wos-haengd-de-raatschn-aa-schoo-aum-hallofoon', 'Kaum passiad wos, hängd de Raatschn aa schoo aum Hallofoon!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Kaum passiert was, hängt die Ratsche auch schon am Hallofon!', '[{"kategorie": "wörtlich", "text": "\"Kaum passiert was, hängt die Tratsche auch schon am Telefon!\"  2. \"Sobald irgendetwas passiert, greift die Tratschziege auch schon zum Hörer!\"  3. \"Kaum rührt sich was, vergehen keine fünf Minuten, und die Klatschtante hängt schon in der Leitung!\""}]'::jsonb, ''),
  ('dea-oasch-kummd-mit-ana-raatschn-untan-mauntl-des-is-nimma-lustig', 'Dea Oasch kummd mit ana Raatschn untan Mauntl - des is nimma lustig!', '', '', '', 'Wiener Gaunersprache', 'Der Arsch kommt mit einer Ratschen unter''m Mantel - das ist nicht mehr lustig!', '[{"kategorie": "wörtlich", "text": "\"Der Dreckskerl kommt mit einer Maschinenpistole unter''m Mantel - das ist nicht mehr lustig!\"  2. \"Der Bastard hat ’ne Maschinenknarre dabei – das ist kein Spaß mehr!\"  3. \"Der Typ kommt mit ''nem Eisen unterm Mantel – da ist Schluss mit lustig!\""}]'::jsonb, ''),
  ('aum-oostasunndoog-raatschn-de-ministrantn-zum-letztn-moi-bevua-de-glockn-wiida-leitn', 'Aum Oostasunndoog raatschn de Ministrantn zum letztn Moi, bevua de Glockn wiida leitn!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Am Ostersonntag ratschen die Ministranten zum letzten Mal, bevor die Glocken wieder läuten!', '[{"kategorie": "wörtlich", "text": "\"Am Ostersonntag drehen die Ministranten zum letzten Mal ihre Ratschen, bevor das Glockengeläut wieder zurückkehrt!\"  2. \"Bevor am Ostersonntag die Glocken wieder läuten, ratschen die Ministranten noch ein allerletztes Mal!\"  3. \"Noch einmal ratscht es durch den Ort, bevor die Glocken den Ostersonntag einläuten!\""}]'::jsonb, ''),
  ('de-zwaa-schdengan-seit-aana-schdund-aum-goatnzaun-und-raatschn-iwa-gott-und-de-woeoed', 'De zwaa schdengan seit aana Schdund aum Goatnzaun und raatschn iwa Gott und de Wööd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die zwei stehen seit einer Stunde am Gartenzaun und ratschen über Gott und die Welt!', '[{"kategorie": "wörtlich", "text": "\"Seit einer Stunde stehen die beiden am Gartenzaun und quatschen über Gott und die Welt!\"  2. \"Die zwei kleben seiteiner Stunde am Gartenzaun und schwafeln sich die Seele aus’m Leib!\"  3. \"Seit einer Stunde stehen die beiden am Gartenzaun und blasen sich gegenseitig die Ohren voll!\""}]'::jsonb, ''),
  ('waunns-amoi-raatschd-brauchsd-nimma-vahaundln', 'Waunns amoi raatschd, brauchsd nimma vahaundln!', '', '', '', 'Wiener Gaunersprache', 'Wenn es einmal ratscht, brauchst du nicht mehr verhandeln!', '[{"kategorie": "wörtlich", "text": "\"Wenn die Maschinenpistole mal knattert, brauchst du nicht mehr zu verhandeln!\"  2. \"Wenn’s einmal ratscht, ist Reden vorbei!\"  3. \"Wenn mal die Ratsche läuft, ist Schluss mit Palavern!\""}]'::jsonb, ''),
  ('de-oide-raatschkaatl-waass-imma-ois-easchde-wea-von-wem-schwaunga-is-oda-wea-si-von-wem-hod-scheidn-lossn', 'De oide Raatschkaatl waass imma ois Easchde, wea von wem schwaunga is oda wea si von wem hod scheidn lossn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die alte Ratschkathl weiß immer als Erste, wer von wem schwanger ist oder wer sich von wem hat scheiden lassen!', '[{"kategorie": "wörtlich", "text": "\"Die alte Tratschziege weiß immer als Erste, wer von wem ein Kind erwartet oder wer sich von wem getrennt hat!\"  2. \"Die alte Tratschtante hat immer als Erste die neuesten Informationen darüber, wer schwanger ist oder wer sich getrennt hat!\"  3. \"Wenn’s um Schwangerschaften oder Scheidungen geht, ist die alte Tratsche schneller als jedes Amtsblatt!\""}]'::jsonb, ''),
  ('do-rennd-da-raatsch', 'Do rennd da Raatsch!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da rennt der Ratsch!', '[{"kategorie": "wörtlich", "text": "\"Da rennt der Tratsch!\"  2. \"Da ist das Geschwätz am Laufen!\"  3. \"Da brodelt die Gerüchteküche!\""}]'::jsonb, ''),
  ('oone-de-taegliche-raatscharei-warads-graetzl-fost-faad', 'Oone de tägliche Raatscharei warads Grätzl fost faad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ohne die tägliche Ratscherei wäre das Grätzl fast fad!', '[{"kategorie": "wörtlich", "text": "\"Ohne die tägliche Tratscherei wär''s in unserem Viertel fast langweilig!\"  2. \"Der tägliche Tritsch-Tratsch ist der eigentliche Unterhaltungswert unseres Grätzls!\"  3. \"Ohne den täglichen Tratsch wär das ganze Stadtviertel kulturell unterversorgt!\""}]'::jsonb, ''),
  ('soog-zum-raupfaung-jo-nii-schoanschdaa-waeu-des-tuad-ma-ind-uawaschln-waeae', 'Soog zum Raupfaung jo nii ''Schoanschdaa'' - wäu des tuad ma ind Uawaschln wää!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sag zum Rauchfang niemals Schornstein, denn das tut mir in den Ohrwascheln weh!', '[{"kategorie": "wörtlich", "text": "\"Nenn den Rauchfang bloß nicht Schornstein - sonst krieg ich Ohrenschmerzen!\"  2. \"Es heißt ''Rauchfang'' und nicht ''Schornstein'' - wenn du ''Schornstein'' sagst, zuckt’s mir im Ohr!\"  3. \"Sag Rauchfang, alles andere is akustische Körperverletzung!\""}]'::jsonb, ''),
  ('zu-sueuewoeoesta-kriagt-da-raupfaungkeara-mea-zuagschdeckt-ois-a-koeoena-in-da-bestn-nocht-schliisslich-bringta-s-glick-untad-leit', 'Zu Süüwöösta kriagt da Raupfaungkeara mea zuagschdeckt ois a Kööna in da bestn Nocht - schliisslich bringta s''Glick untad Leit!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Zu Silvester kriegt der Rauchfangkehrer mehr zugesteckt als ein Kellner in der besten Nacht - schließlich bringt er das Glück unter die Leut''!', '[{"kategorie": "wörtlich", "text": "\"Zu Silvester sind die Taschen des Rauchfangkehrers voller als jede Kellnerschürze, denn Glück lässt man sich was kosten!\"  2. \"Zu Silvester sammelt der Rauchfangkehrer mehr ein als jeder Kellner am Rekordabend – Glück zu bringen zahlt sich eben aus!\"  3. \"Der Rauchfangkehrer macht am Silvestertag mehr Geschäft als der beste Kellner der Stadt - denn fürs Glück, das er bringt, zeigt sich jeder erkenntlich!\""}]'::jsonb, ''),
  ('de-oidn-raupfaungtaubm-schaun-aus-ois-haedns-a-leebdoch-laung-im-kamin-ghaust', 'De oidn Raupfaungtaubm schaun aus, ois hädns a Leebdoch laung im Kamin ghaust!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die alten Rauchfangtauben schauen aus, als hätten sie ein Lebtag lang im Kamin gehaust!', '[{"kategorie": "wörtlich", "text": "\"Die alten Trauerwitwen in schwarz schauen aus, als hätten sie ein Leben lang im Rauchfang gesessen!\"  2. \"Schwarze Witwen trauern nicht - diese alten Rauchfangtauben schrecken bloß kleine Kinder!\"  3. \"Die hässlichen, alten Weiber, die bis zu ihrem Tod tagein, taugaus nur schwarze Trauerkleidung tragen, schauen alle aus wie halbverweste ''Rauchfangtauben''!\""}]'::jsonb, ''),
  ('du-oide-varuussde-raupfaungtaubm', 'Du oide, varuussde Raupfaungtaubm!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du alte, verrußte Rauchfangtaube!', '[{"kategorie": "wörtlich", "text": "\"Du alte, verrußte Friedhofskrähe!\"  2. \"Du alte, schwarze Witwe!\"  3. \"Du alte, verrußte Nachteule!\""}]'::jsonb, ''),
  ('ea-raunzd-ollawaeu-iwas-weeda-egal-wias-is', 'Ea raunzd ollawäu iwas Weeda - egal, wias is!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er raunzt alleweil über das Wetter - egal, wie''s ist!', '[{"kategorie": "wörtlich", "text": "\"Er jammert ständig übers Wetter - egal, wie''s draußen ausschaut!\"  2. \"Der lamentiert bei jedem Wetter - egal, ob''s schüttet oder die Sonne scheint!\"  3. \"Sonne ist zu heiß, Regen zu nass: Anlass zum Jeiern gibt’s für ihn immer!\""}]'::jsonb, ''),
  ('waunn-raunzn-goeoed-bringad-warad-mei-oida-schoo-laengst-millionaea', 'Waunn Raunzn Gööd bringad, warad mei Oida schoo längst Millionäa!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn Raunzen Geld brächte, wäre mein Alter schon längst Millionär!', '[{"kategorie": "wörtlich", "text": "\"Könnte er fürs Raunzen Geld kassieren, wäre mein Alter schon längst steinreich!\"  2. \"Könnte man mit Nörgeln und Jammern Geld verdienen, wär mein Alter längst Multimillionär!\"  3. \"Wäre ständiges Granteln eine Einnahmequelle, würde mein Alter längst Geld scheißen!\""}]'::jsonb, ''),
  ('stott-z-jeian-kunntad-ma-doch-aafoch-wos-dageeng-tuan', 'Stott z''jeian, kunntad ma doch aafoch wos dageeng tuan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Statt zu jeiern, könnte man doch einfach was dagegen tun!', '[{"kategorie": "wörtlich", "text": "\"Statt dauernd zu meckern, könnte man doch auch einfach handeln!\"  2. \"Anstatt zu raunzen, wär’s g’scheiter, was dagegen zu unternehmen!\"  3. \"Hör auf zu jeiern und tu endlich was!\""}]'::jsonb, ''),
  ('do-hueuefd-ka-jeian-und-ka-suudan-de-klaane-lossd-si-hoid-ned-puudan', 'Do hüüfd ka Jeian und ka Suudan, de Klaane lossd si hoid ned puudan!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Da hilft kein Jeiern und kein Sudern - die Kleine lässt sich halt nicht pudern!', '[{"kategorie": "wörtlich, Scherzreim", "text": "\"Da hilft kein Raunzen und kein Plärren – die Kleine will gefickt nicht werden!\"  2. \"Da hilft kein Jammern und kein Fleh''n – Bumsen wird bei der nicht geh''n!\"  3. \"Und wenn du jeierst bis morgen früh – vögeln lässt sich die Kleine nie!\""}]'::jsonb, ''),
  ('ea-is-hoid-unsa-klaana-raunza-oone-sei-taegliches-suudan-daed-uns-fost-schoo-wos-oogee', 'Ea is hoid unsa klaana Raunza - oone sei tägliches Suudan däd uns fost schoo wos oogee!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er ist halt unser kleiner Raunzer – ohne sein tägliches Sudern tät'' uns was schon was abgehen!', '[{"kategorie": "wörtlich", "text": "\"Er ist halt unser kleiner Dauerjammerer – ohne seine tägliche Suderei tät'' uns echt was fehlen!\"  2. \"Er ist eben unser Haus-Grantler – ohne sein tägliches Sudern wär’s nur halb so lustig!\"  3. \"Unser kleiner Meckerkopf gehört einfach dazu - ein Tag ohne sein Sudern wär für uns fast unheimlich!\""}]'::jsonb, ''),
  ('ea-is-a-richtiga-raunzschaeaedl-egal-wos-is-nix-passd-eam', 'Ea is a richtiga Raunzschäädl - egal wos is, nix passd eam!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er ist ein richtiger Raunzschädel – egal was ist, nichts passt ihm!', '[{"kategorie": "wörtlich", "text": "\"Er ist ein echter Meckerkopf – egal was passiert, ihm ist nichts recht!\"  2. \"Er ist ein Grantler durch und durch - immer nur am Motzen!\"  3. \"Der Typ ist ein Berufsraunzer - er findet an allem was auszusetzen!\""}]'::jsonb, ''),
  ('hock-di-nua-ned-neebm-de-raunzarin-de-saugd-da-de-letzde-schdimmung-ausn-bluad', 'Hock di nua ned neebm de Raunzarin - de saugd da de letzde Schdimmung ausn Bluad!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Hock dich nur nicht neben die Raunzerin – die saugt dir die letzte Stimmung aus dem Blut!', '[{"kategorie": "wörtlich", "text": "\"Setz dich nur nicht neben diese Jammerliese - die saugt dir die gute Laune aus dem Blut wie ein Zeck!\"  2. \"Bleib bloß weg von dieser Jammerziege – die zieht dir deine letzte Fröhlichkeit aus’m Leib!\"  3. \"Setz dich bloß nicht zu dieser Dauergrantlerin - die jammert dir die letzte Gaudi aus der Seele!\""}]'::jsonb, ''),
  ('dera-ia-raunzarei-geed-ma-aum-keks', 'Dera ia Raunzarei geed ma aum Keks!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Die Raunzerei von ihr geht mir am Keks!', '[{"kategorie": "wörtlich", "text": "\"Ihr ständiges Gejammere geht mir auf den Wecker!\"  2. \"Ihr ewiges Genörgel geht mir am Arsch!\"  3. \"Ihr dauerndes Gemecker geht mir echt auf den Geist!\""}]'::jsonb, ''),
  ('de-wiatin-is-a-eewiche-suudarantin-dera-kaunnsd-nix-recht-mochn-fia-de-is-imma-ollas-oasch', 'De Wiatin is a eewiche Suudarantin - dera kaunnsd nix recht mochn, fia de is imma ollas oasch!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Die Wirtin ist ''ne ewige Suderantin - der kannst nichts rechtmachen – für die ist immer alles ''arsch''!', '[{"kategorie": "wörtlich", "text": "\"Die Wirtin ist eine Dauersuderantin – egal was du machst, für sie ist immer alles ''oasch''!\"  2. \"Die Wirtin ist eine klassische Berufsraunzerin – nichts ist ihr recht, alles ist ''oarsch''!\"  3. \"Die Wirtin, unsere ewige Nörglerin - an allem hat sie was auszusetzen, nichts passt ihr!\""}]'::jsonb, ''),
  ('da-boodn-is-reina-kiis-hoat-locka-und-zum-gee-a-graus', 'Da Boodn is reina Kiis - hoat, locka und zum Gee a Graus!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Boden ist reiner Kies - hart, locker und zum Gehen ein Graus!', '[{"kategorie": "wörtlich", "text": "\"Am Boden liegt nichts als Kies – hart, rutschig und total ungut zum Gehen!\"  2. \"Das Erdreich besteht nur aus Kies – fest, schlüpfrig und äußerst unangenehm zum Gehen!\"  3. \"Der Untergrund ist nichts als Kies – hart, lose und äußerst beschwerlich zum Laufen!\""}]'::jsonb, ''),
  ('i-hob-mea-kiis-im-beasl-ois-im-vuagoatn-und-des-wueue-wos-haassn', 'I hob mea Kiis im Beasl ois im Vuagoatn – und des wüü wos haassn!', '', '', '', 'Wiener Gaunersprache', 'Ich hab mehr Kies im Börsl als im Vorgarten – und das will was heißen!', '[{"kategorie": "wörtlich", "text": "\"Ich hab mehr Kies im Portemonnaie als im Vorgarten – und das will was heißen!\"  2. Ich hab mehr Schotter im Geldbeutel als im Vorgarten – und das will was heißen!  3. Ich habe mehr Kies in der Tasche als vor der Hütte – und das will was heißen!"}]'::jsonb, ''),
  ('des-gaunze-geraunze-mochds-aa-ned-bessa-sauf-dei-bia-und-sei-schdueue', 'Des gaunze Geraunze mochds aa ned bessa - sauf dei Bia und sei schdüü!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Das ganze Geraunze macht''s auch nicht besser - sauf dein Bier und sei still!', '[{"kategorie": "wörtlich", "text": "\"Mit dem Gesudere wird’s auch nicht besser – trink dein Bier und sei ruhig!\"  2. \"Spar dir das ganze Gejeiere - davon wird das Bier auch nicht besser!\"  3. \"Dein ständiges Gejammer hilft da auch nichts – sauf und sei still!\""}]'::jsonb, ''),
  ('waunnsd-dera-ia-raunzada-schdimm-laenga-heast-faeun-da-d-uawaschln-oo', 'Waunnsd dera ia raunzada Schdimm länga heast, fäun da d''Uawaschln oo!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn du die raunzerte Stimme von der länger hörst, faulen dir die Ohrwascheln ab!', '[{"kategorie": "wörtlich", "text": "\"Wenn die mit ihrer weinerlichen Stimme länger auf dich einredet, fallen dir die Ohren ab!\"  2. \"Wenn du dich der jammernden Stimme dieser Frau noch länger aussetzt, wirst du deine Ohren verlieren!\"  3. \"Noch ein Satz in diesem wehklagenden Ton, und ich bin [[derisch]]!\""}]'::jsonb, ''),
  ('sitz-ned-so-raunzich-umanaunda-loch-sauf-oda-gee-haam', 'Sitz ned so raunzich umanaunda - loch, sauf oda gee haam!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Sitz nicht so raunzig umeinander - lach'', sauf'' oder geh heim!', '[{"kategorie": "wörtlich", "text": "\"Sitz nicht so grantig rum – hab Spaß mit uns, trink einen mit uns oder geh nach Hause!\"  2. \"Setz nicht so ein weinerliches Gesicht auf - lach mit uns, trink mit uns oder geh heim!\"  3. \"Hör auf mit dem Gejammer – oder mach dich vom Acker, bevor uns das Bier noch sauer wird!\""}]'::jsonb, ''),
  ('olle-reibm-si-de-haend-owa-ned-waeus-a-marii-gibd-sondan-waeus-so-koid-is', 'Olle reibm si de Händ - owa ned wäus a Marii gibd, sondan wäus so koid is!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Alle reiben sich die Hände - aber nicht weil''s ''ne Marie gibt, sondern weil''s so kalt ist!', '[{"kategorie": "wörtlich", "text": "\"Alle reiben sich die Hände - aber nicht weil''s Geld gibt, sondern weil''s so kalt ist!\"  2. \"Jeder rubbelt sich die Hände – nicht aus Geldgier, sondern weil es so frostig ist!\"  3. \"Alle reiben sich die Hände - nicht etwa, weil''s Kohle gibt, sondern weil''s eiskalt ist!\""}]'::jsonb, ''),
  ('reib-man-feidl-aus-da-toschna', 'Reib man Feidl aus da Toschna!', '', '', '', 'Wiener Gaunersprache', 'Reib'' mir den Feitel aus der Tasche!', '[{"kategorie": "wörtlich", "text": "\"Gib mir das Messer aus der Tasche!\"  2. \"Hol mir das Messer aus der Tasche!\"  3. \"Reich mir das Messer aus der Tasche!\"  4. \"Her mit dem Feitel, der steckt in der Tasche!\""}]'::jsonb, 'wem wos reibm'),
  ('reib-ma-an-fuffi-kriagsd-eam-muang-aeae-wiida-zruck', 'Reib ma an Fuffi - kriagsd eam muang ää wiida zruck!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Reib mir einen Fuffi - kriegst ihn morgen eh wieder zurück!', '[{"kategorie": "wörtlich", "text": "\"Borg mir einen Fünziger - bekommst ihn gleich morgen wieder zurück!\"  2. \"Leih mir schnell einen Fünfziger, spätestens morgen wieder retour!\"  3. \"Mach mir einen Fünfziger locker, morgen hast ihn eh wieder zurück!\""}]'::jsonb, ''),
  ('in-gree-muassd-frisch-reibm-sunst-hoda-kaa-schaeafe', 'In Gree muassd frisch reibm, sunst hoda kaa Schäafe!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Den Kren musst du frisch reiben, sonst hat er keine Schärfe!', '[{"kategorie": "wörtlich", "text": "\"Den Kren immer frisch reiben, sonst verliert er seine Schärfe!\"  2. \"Meerrettich gehört frisch gerieben, sonst ist die Schärfe weg!\"  3. \"Kren erst direkt vor dem Servieren reiben, sonst verfliegt die Schärfe!\""}]'::jsonb, ''),
  ('wem-wos-reibm', 'wem wos reibm', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem etwas reiben', '[{"kategorie": "wörtlich", "text": "\"jemandem etwas herausrücken\""}, {"kategorie": "", "text": "\"jemandem etwas reichen\""}, {"kategorie": "", "text": "\"jemandem etwas in die Hand drücken\""}]'::jsonb, ''),
  ('gee-reib-di', 'Gee, reib di!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Geh, reib dich!', '[{"kategorie": "wörtlich", "text": "\"Mann, hau ab!\"  2. \"[[Hau]] di in Rettich!\"  3. [[Hau di iwad Heisa!]]  4.[[Schau, dassd weidakummst!]]  5. [[Gee päule!]]  6. [[Moch a Woikn!]]  7. [[Draa di!]]  8. [[Vazupf di!]]"}]'::jsonb, ''),
  ('es-riad-si-nix-und-es-reibd-si-nix', 'Es riad si nix und es reibd si nix!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Es rührt sich nichts und es reibt sich nichts!', '[{"kategorie": "wörtlich", "text": "\"Da tut sich rein gar nichts!\"  2. \"Hier herrscht tote Hose!\"  3. \"Da ist absolut nichts los!\"  4. \"Hier ist Land unter!\""}]'::jsonb, ''),
  ('reib-ume', 'Reib ume!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Reib rüber!', '[{"kategorie": "wörtlich", "text": "\"Gib her!\"  2. Reich rüber!   3. Her damit!  4. Rück raus!  5. Schieb rüber!  6. Her mit dem Ding!"}]'::jsonb, ''),
  ('reib-ume-de-marii', 'Reib ume de Marii!', '', '', '', 'Wiener Gaunersprache', 'Reib rüber die Marie', '[{"kategorie": "wörtlich", "text": "\"Schieb rüber die Kohle!\"  2. \"Rück raus den [[Flieder]]!\"  3. \"Schieb rüber den Zaster!\"  [[Reib ume des Geaschdl!]]"}]'::jsonb, ''),
  ('reib-ume-des-geaschdl', 'Reib ume des Geaschdl!', '', '', '', 'Wiener Gaunersprache', 'Reib rüber das Gerstel', '[{"kategorie": "wörtlich", "text": "\"Schieb rüber die Kohle!\"  2. \"Rück raus den [[Flieder]]!\"  3. \"Schieb rüber den Zaster!\"  [[Reib ume de Marie!]]"}]'::jsonb, 'Reib ume de Marii!'),
  ('wem-wos-umereibm', 'wem wos umereibm', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem etwas ummereiben', '[{"kategorie": "wörtlich", "text": "\"jemandem etwas rüberreiben\" (Kompositum aus dem abtrennbaren Präfix \"ume\"=\"rüber\" und \"reiben\"=\"schieben\")"}, {"kategorie": "allg.", "text": "\"jemandem etwas rüberschieben\""}, {"kategorie": "", "text": "\"jemandem etwas rüberreichen\""}, {"kategorie": "", "text": "\"jemandem etwas rausrücken\""}]'::jsonb, ''),
  ('moch-kaane-woeoen-sunst-reib-i-da-de-lauscha-und-des-uanreiwal-vagissd-dei-leebdooch-nimma', 'Moch kaane Wöön, sunst reib I da de Lauscha - und des Uanreiwal vagissd dei Leebdooch nimma!', '', '', '', 'Wiener Gaunersprache', 'Mach keine Wellen, sonst reib ich dir die Lauscher - und das Ohrenreiberl vergisst du dein Lebtag nimmer!', '[{"kategorie": "wörtlich", "text": "\"Kein Aufstand, sonst pack ich dich bei den Ohren – und den Ohrenquetscher merkst du dir ein Leben lang!\"  2. \"Mach keinen Zores, sonst dreh ich dir die Ohren lang - und das vergisst du ein Leben lang nicht mehr!\"  3. \"Bleib ruhig, Freundchen, sonst glüh''n dir gleich die Lauscher - und den Doppelohrreiber merkst du dir fürs Leben!\""}]'::jsonb, ''),
  ('ea-hod-eam-aum-boodn-festgnoogld-und-mit-an-giftichn-uanreiwal-zamueabd', 'Ea hod eam aum Boodn festgnoogld und mit an giftichn Uanreiwal zamüabd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Er hat ihn am Boden festgenagelt und mit einem giftigen Ohrenreiberl zermürbt!', '[{"kategorie": "wörtlich, Freistilringen", "text": "\"Er hat ihn am Boden fixiert und mit einer giftigen Ohrwaschelwalze zermürbt!\"  2. \"Er hat ihn am Boden eingespannt und mit einem schmutzigen Ohrenkneifer mürbe gemacht!\"  3. \"Er hielt ihn flach und zermürbte ihn mit einem giftigen Ohrenschleifer!\""}]'::jsonb, ''),
  ('moch-kaane-woeoen-sunst-reib-i-da-de-lauscha-und-des-uawaschlreiwal-vagissd-dei-leebdooch-nimma', 'Moch kaane Wöön, sunst reib I da de Lauscha - und des Uawaschlreiwal vagissd dei Leebdooch nimma!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mach keine Wellen, sonst reib ich dir die Lauscher - und das Ohrwaschlreiberl vergisst du dein Lebtag nimmer!', '[{"kategorie": "wörtlich", "text": "\"Kein Aufstand, sonst pack ich dich bei den Ohren – und den Ohrenquetscher merkst du dir ein Leben lang!\"  2. \"Mach keinen Zores, sonst dreh ich dir die Ohren lang - und das vergisst du ein Leben lang nicht mehr!\"  3. \"Bleib ruhig, Freundchen, sonst glüh''n dir gleich die Lauscher - und den Doppelohrreiber merkst du dir fürs Leben!\""}]'::jsonb, ''),
  ('da-kaumpf-is-kippd-wiara-eam-a-giftichs-uawaschlreiwal-vapassd-hod', 'Da Kaumpf is kippd, wiara eam a giftichs Uawaschlreiwal vapassd hod!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Kampf ist gekippt, wie er ihm ein giftiges Ohrwaschelreiberl verpasst hat!', '[{"kategorie": "wörtlich, Freistilringen", "text": "\"Der Kampf kippte, als er ihn mit einer giftigen Ohrwaschelwalze zermürbte!\"  2. \"Der Kampf drehte sich, als er in Bodenlage zu einem giftigen Unterschenkel-Ohrreiber ansetzte!\"  3. Er hat ihn am Boden eingespannt und mit einem schmutzigen Ohrenkneifer mürbe gemacht!\"  3.  \"Der Kampf schlug um, als er seinen brutalen Unterschenkel-Ohrreiber setzen konnte!\""}]'::jsonb, ''),
  ('reib-eam-de-lauscha', 'Reib eam de Lauscha!', '', '', '', 'Echte Wiener Schmähperlen', 'Reib ihm die Lauscher!', '[{"kategorie": "wörtlich", "text": "\"Verpass ihm ein [[Ohrenreiberl]]!\"  2. (Publikumszuruf beim Freistilringen): \"Verpass ihm eine Lauscherpolitur!\"  3. \"Nimm ihn in die Unterschenkelzange!\"  4. \"Verpass ihm einen Unterschenkel-Ohrenreiber!\"  5. \"Fahr die Ohrwaschelwalze aus!\""}]'::jsonb, ''),
  ('heast-reib-ume-an-tschick', 'Heast, reib ume an Tschick!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Los, reib rüber einen Tschick!', '[{"kategorie": "wörtlich", "text": "\"Hey, gib her ''ne Zigarette!\"  2. \"Kumpel, reich mir ''ne Zigarette!\"  3. \"Los, rück ''ne Zigarette raus!\""}]'::jsonb, ''),
  ('reiwal1', 'Reiwal1', 'das', '', '', 'Grundwortschatz Wienerisch', 'Reiberl', '[{"kategorie": "wörtlich", "text": "\"Reiberl\" (Verkleinerungsform von \"Reibe\", vom mittelhochdeutschen \"rīben\"=\"reiben\")"}, {"kategorie": "allg.", "text": "Küchenreibe, Raspel, Reibeisen"}, {"kategorie": "Mechanikerjargon", "text": "Kolbenreiber, Kolbenfresser, Motorschaden"}, {"kategorie": "scherzhaft für", "text": "kleine Abreibung, kleine Rangelei, kleines Handgemenge"}]'::jsonb, 'Nimms feine Reiwal fiad Limonischoin - sunst wiads z''bitta!'),
  ('nimms-feine-reiwal-fiad-limonischoin-sunst-wiads-z-bitta', 'Nimms feine Reiwal fiad Limonischoin - sunst wiads z''bitta!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Nimm das feine Reiberl für die Zitronenschale - sonst wird’s zu bitter!', '[{"kategorie": "wörtlich, Küchenjargon", "text": "\"Mit dem feinen Reiberl arbeiten, nicht grob – die Schale wird sonst bitter!\"  2. \"Zitronenzesten nur übers feine Reiberl, die grobe Reibe gibt Bitterstoffe!\"  3. \"Nimm die feine Raspel für die Zitrone - wir wollen Aroma, keine Bitterkeit!\""}]'::jsonb, ''),
  ('da-muarl-hod-a-reiwal-ghobd-do-hods-in-koibm-sauwa-gfressn', 'Da Muarl hod a Reiwal ghobd - do hods in Koibm sauwa gfressn!', '', '', '', 'Wiener Mechaniker-Slang', 'Der Murl hat ein Reiberl g’habt - da hat''s Kolben sauber g’fressen!', '[{"kategorie": "wörtlich, Mechanikerjargon", "text": "\"Der Motor hat leider einen schweren Kolbenschaden erlitten - sauber angerieben, nichts mehr zu retten!\"  2. \"Der Motor hat sich selbst zerlegt - da hat''s den Kolben gefressen!\"  3. \"Der Motor hat sich festgelaufen - klassischer Kolbenreiber!\""}]'::jsonb, ''),
  ('mia-haum-uns-ned-geschleegad-hea-rood-des-woa-nuara-klaans-reiwal', 'Mia haum uns ned geschleegad, Hea Rood - des woa nuara klaans Reiwal!', '', '', '', 'Wiener Gaunersprache', 'Wir haben uns nicht geschlägert, Herr Rat - das war nur ein kleines Reiberl!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Wir haben uns keine Schlägerei geliefert, Herr Richter - das war nur ein kleines Gerangel!\"  2. \"Das war keine Prügelei, Herr Rat - das war nur ein kleine Rangelei!\"  3. \"Von einer wilden Schlägerei kann keine Rede sein, Herr Richter - das war bestenfalls ein kleines Handgemenge!"}]'::jsonb, ''),
  ('reiwal2', 'Reiwal2', 'das', '', '', 'Wiener Gaunersprache', 'Räuberl', '[{"kategorie": "wörtlich", "text": "\"Räuberl\" (Verkleinerungsform von \"Raub\", vom mittelhochdeutschen \"roup\"=\"Raub\")"}, {"kategorie": "Gaunerjargon, verniedlichend für", "text": "\"Räuberchen\", \"Raub\", \"Raubüberfall\", \"Straßenraub\""}]'::jsonb, 'Des woa kaa groosse Soch - nuara klaans Reiwal glei ums Eck!'),
  ('des-woa-kaa-groosse-soch-nuara-klaans-reiwal-glei-ums-eck', 'Des woa kaa groosse Soch - nuara klaans Reiwal glei ums Eck!', '', '', '', 'Wiener Gaunersprache', 'Das war keine große Sache - nur ein kleines Räuberchen gleich ums Eck!', '[{"kategorie": "wörtlich", "text": "\"Das war kein großes Ding - bloß ein kleiner Raub gleich um die Ecke!\"  2. \"Ach was, das war nur ein kleiner Raubüberfall - ''ne fixe Nummer gleich um die Ecke!\"  3. \"Das war ’ne harmlose Nummer, Bruder - nur ein kleiner Straßenraub im Vorbeigehen!\""}]'::jsonb, ''),
  ('pass-aufd-finga-auf-de-reibm-is-echt-schoaf', 'Pass aufd Finga auf - de Reibm is echt schoaf!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Pass auf die Finger auf, die Reibe ist echt scharf!', '[{"kategorie": "wörtlich", "text": "\"Achtung mit den Fingern – die Küchenreibe ist echt scharf!\"  2. \"Pass auf, sonst raspelst du dir mit der Reibe noch die Finger weg!\"  3. \"Gib Acht, dass du mit den Fingern nicht abrutschst - die Reibe ist echt bissig!\""}]'::jsonb, ''),
  ('i-foa-de-reibm-bis-ausaranaunda-foid', 'I foa de Reibm, bis ausaranaunda foid!', '', '', '', 'Wiener Mechaniker-Slang', 'Ich fahr die Reibe, bis sie auseinanderfällt!', '[{"kategorie": "wörtlich", "text": "\"Ich fahr die Karre, bis sie endgültig den Geist aufgibt!\"  2. \"Ich reit die Mühle bis zum letzten Atemzug!\"  3. \"Ich behalt die Schüssel, bis sie mir unter’m Hintern zerfällt!\""}]'::jsonb, ''),
  ('moch-bei-da-nocht-in-reiwa-guad-zua', 'Moch bei da Nocht in Reiwa guad zua!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Mach bei der Nacht den Reiber gut zu!', '[{"kategorie": "wörtlich", "text": "\"Mach den Fensterriegel für die Nacht richtig zu!\"  2. \"Den Fensterhaken in der Nacht ganz einrasten lassen!\"  3. \"Denk dran, die Fenstersicherung noch vor dem Schlafengehen festzumachen!\""}]'::jsonb, ''),
  ('dea-is-oone-marii-kumman-do-woa-de-kaeularei-vuaprogrammiad', 'Dea is oone Marii kumman - do woa de Käularei vuaprogrammiad!', '', '', '', 'Wiener Gaunersprache', 'Der ist ohne Marie gekommen - da war die Keilerei vorprogrammiert!', '[{"kategorie": "wörtlich", "text": "\"Der ist ohne Geld erschienen - da war die Keilerei vorprogrammiert!\"  2. \"Der ist mit leeren Taschen aufgeschlagen – da war die Schlägerei beschlossene Sache!\"  3. \"Er kam blank rein, also flogen die Fäuste!\""}]'::jsonb, ''),
  ('drei-drei-drei-issos-kaeularei', 'Drei, drei, drei - Issos Käularei!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Drei, drei, drei - Issos Keilerei!', '[{"kategorie": "wörtlich", "text": "\"3-3-3 - Issos Keilerei!\" (schulische Eselsbrücke zur dauerhaften Einprägung der Jahreszahl 333 v. Chr. für die Schlacht bei Issos zwischen Alexander dem Großen und dem persischen Großkönig Dareios III., bei der das makedonische Heer die Perser besiegte [\"Issos\" liegt in der heutigen Südtürkei, in der Nähe der Stadt İskenderun, Provinz Hatay, wo sich eine enge Küstenebene zwischen Meer und Gebirge erstreckt]"}, {"kategorie": "", "text": "\"Drei-drei-drei – Issos Prügelei!\"  3. \"Drei-drei-drei – Issos Rauferei!\""}]'::jsonb, ''),
  ('mit-wem-a-reiwarei-haum', 'mit wem a Reiwarei haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'mit jemandem eine Reiberei haben', '[{"kategorie": "wörtlich", "text": "\"eine Auseinandersetzung mit jemandem haben\""}, {"kategorie": "", "text": "\"mit jemandem in Streit geraten\""}, {"kategorie": "", "text": "\"eine Meinungsverschiedenheit mit jemandem haben\""}]'::jsonb, 'Waunn dea auftauchd, hob I imma iagendwööche Reiwarein mit eam - meistns geeds umd Marii!'),
  ('waunn-dea-auftauchd-hob-i-imma-iagendwoeoeche-reiwarein-mit-eam-meistns-geeds-umd-marii', 'Waunn dea auftauchd, hob I imma iagendwööche Reiwarein mit eam - meistns geeds umd Marii!', '', '', '', 'Wiener Gaunersprache', 'Wenn der auftaucht, habe ich immer irgendwelche Reibereien mit ihm - meistens geht''s um die Marie!', '[{"kategorie": "wörtlich", "text": "\"Wenn der auftaucht, kommt''s immer zu irgendwelchen Streitigkeiten mit ihm - meistens geht''s ums Geld!\"  2. \"Sobald der aufschlägt, gibt’s Stress – fast immer wegen Kohle!\"  3. \"Wo der auftaucht, gibt’s Streit - und es geht fast immer ums Geld!\""}]'::jsonb, 'mit wem a Reiwarei haum'),
  ('bei-de-inuit-gibds-zua-begrueuessung-a-siasses-noosnreiwal', 'Bei de Inuit gibds zua Begrüüssung a siasses Noosnreiwal!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bei den Inuit gibt''s zur Begrüßung ein süßes Nasenreiberl!', '[{"kategorie": "wörtlich", "text": "\"Bei den Inuit wird man mit einem süßen Nasenreiben begrüßt!\"  2. \"Der Eskimokuss ersetzt bei den Inuit den Händedruck zur Begrüßung!\"  3. \"Bei den Inuit ist ein süßes Nasenreiben Teil der Begrüßungskultur!\""}]'::jsonb, ''),
  ('friara-haum-de-frechn-schuibuam-vom-leara-a-noosnreiwal-kriagd-und-a-rua-woa', 'Friara haum de frechn Schuibuam vom Leara a Noosnreiwal kriagd - und a Rua woa!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Früher haben die frechen Schulbuben vom Lehrer ein Nasenreiberl bekommen - und dann war Ruhe!', '[{"kategorie": "wörtlich", "text": "\"Früher wurden freche Schüler von ihren Lehrern mit einem Nasenstüber gezüchtigt - und dann war die Ordnung wiederhergestellt!\"  2. \"Seinerzeit gab''s für freche Schüler ein Nasenstupserl vom Lehrer - und dann war sofort Frieden!\"  3. \"Ein Nasenreiberl vom Lehrer ersetzte damals lange Ermahnungen - das tat so weh, das der Schüler nachher keinen Mucks mehr von sich gab!\""}]'::jsonb, ''),
  ('noosnreiwal-schdian-aun-schdian-do-woa-de-aunsoog-kloa', 'Noosnreiwal, Schdian aun Schdian - do woa de Aunsoog kloa!', '', '', '', 'Wiener Gaunersprache', 'Nasenreiberl, Stirn an Stirn – da war die Ansage klar!', '[{"kategorie": "wörtlich", "text": "\"Zentimeterabstand, Nase an Nase – Warnung angekommen!\"  2. \"Nase an Nase, keine Luft dazwischen – Klartext ohne Worte!\"  3. \"Stirn an Stirn, Nase an Nase – so nah auf Tuchfühlung, dass Reden überflüssig war!\""}]'::jsonb, ''),
  ('wem-im-reindl-haum', 'wem im Reindl haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden im Reindl haben', '[{"kategorie": "wörtlich", "text": "\"jemanden an der Kandare haben\""}, {"kategorie": "", "text": "jemandem im Schwitzkasten haben"}, {"kategorie": "", "text": "jemanden im Klammergriff haben (auch Sport)"}, {"kategorie": "", "text": "jemanden unter Dauerdruck setzen"}]'::jsonb, 'Ob da easchdn Minuutn woa kloa - mia haum in Geegna im Reindl!'),
  ('ob-da-easchdn-minuutn-woa-kloa-mia-haum-in-geegna-im-reindl', 'Ob da easchdn Minuutn woa kloa - mia haum in Geegna im Reindl!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Ab der ersten Minute war klar - wir haben den Gegner im Reindl!', '[{"kategorie": "wörtlich", "text": "\"Ab Minute eins war klar: wir haben den Gegner im Schwitzkasten!\"  2. Schon ab der ersten Minute hatten wir den Gegner komplett eingekesselt!  3. Die sind ab Anpfiff unter Dauerdruck gestanden!"}]'::jsonb, 'wem im Reindl haum'),
  ('im-reindl-sei', 'im Reindl sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'im Reindl sein', '[{"kategorie": "wörtlich", "text": "\"unter ständigem Druck stehen\" (auch Sport)"}, {"kategorie": "", "text": "unter Dauerbeschuss stehen"}, {"kategorie": "", "text": "an der Kandare sein"}, {"kategorie": "", "text": "im Schwitzkasten des Gegners sein"}]'::jsonb, 'De easchdn zwanzg Minutn woama voi im Reindl - do samma aus da eiganan Höftn ned aussekumma!'),
  ('de-easchdn-zwanzg-minutn-woama-voi-im-reindl-do-samma-aus-da-eiganan-hoeftn-ned-aussekumma', 'De easchdn zwanzg Minutn woama voi im Reindl - do samma aus da eiganan Höftn ned aussekumma!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Die ersten zwanzig Minuten waren wir voll im Reindl - da sind wir aus der eigenen Hälfte nicht rausgekommen!', '[{"kategorie": "wörtlich", "text": "\"Die ersten zwanzig Minuten waren wir voll im Klammergriff des Gegners - da sind wir aus der eigenen Hälfte nicht rausgekommen!\"  2. Die ersten zwanzig Minuten sind wir unter Dauerdruck gestandenj - da sind wir aus der eigenen Hälfte nicht rausgekommen!  3. Die ersten zwanzig Minuten waren wir komplett eingeschnürt und sind aus dem eigenen Strafraum nicht rausgekommen!"}]'::jsonb, 'im Reindl sei'),
  ('s-gaunze-reindl-ausschmiian', 's gaunze Reindl ausschmiian', '', '', '', 'Wiener Sprüche, die sitzen!', 'das ganze Reindl ausschmieren', '[{"kategorie": "wörtlich", "text": "\"etwas bis zum letzten Rest ausschöpfen\""}, {"kategorie": "", "text": "den letzten Tropfen herauskitzeln"}, {"kategorie": "", "text": "alles bis zum Ende auskosten"}]'::jsonb, ''),
  ('heit-zoeoed-jeeda-zentimeta-mia-miassn-ois-aufs-foeoed-bringan-des-gaunze-reindl-ausschmiian', 'Heit zööd jeeda Zentimeta - mia miassn ois aufs Fööd bringan, des gaunze Reindl ausschmiian!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Heute zählt jeder Zentimeter – wir müssen alles auf’s Feld bringen, das ganze Reindl ausschmieren!', '[{"kategorie": "wörtlich", "text": "\"Heute zählt jeder Zentimeter – wir müssen alles auf’s Feld bringen und All-in gehen!\"  2. Heute zählt jeder Meter, jede Sekunde – und wir müssen alles geben, was der Kessel hergibt!  3. Heute geht''s ans Eingemachte - wir müssen bis zum letzten Tropfen Schweiß einfach alles geben!"}]'::jsonb, ''),
  ('a-jeeds-reindl-ausschmiian-miassn', 'a jeeds Reindl ausschmiian miassn', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein jedes Reindl ausschmieren müssen', '[{"kategorie": "wörtlich", "text": "\"nicht nur das Gute, sondern auch alles Schlechte schlucken müssen\""}, {"kategorie": "", "text": "das volle Programm durchmachen müssen"}, {"kategorie": "", "text": "alles bis zum bitteren Ende ertragen müssen"}]'::jsonb, ''),
  ('im-leebm-muassd-hoid-maunchmoi-a-jeeds-reindl-ausschmiian-mitsaumt-de-breesln', 'Im Leebm muassd hoid maunchmoi a jeeds Reindl ausschmiian - mitsaumt de Breesln!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Im Leben musst halt manchmal ein jedes Reindl ausschmieren - mitsamt den Bröseln!', '[{"kategorie": "wörtlich", "text": "\"Manchmal im Leben muss man halt alles schlucken - auch die Krümel!\"  2. Nicht immer läuft’s rund im Leben – doch was man sich einbrockt, musst man auch ausfressen – bis zum letzten Brösel!  3. Das Leben ist kein Wunschkonzert - manchmal muss man eben auch alles Unangenehme schlucken!"}]'::jsonb, 'a jeeds Reindl ausschmiian miassn'),
  ('a-schraufn-muassd-einedraan-genauso-wia-mas-reindl-ausschmiiad-rechtsumadum-und-mit-kroft', 'A Schraufn muassd einedraan genauso wia mas Reindl ausschmiiad - rechtsumadum und mit Kroft!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Eine Schraube musst du genauso reindrehen wie man ein Reindl ausschmiert - rechtsherum und mit Kraft!', '[{"kategorie": "wörtlich", "text": "\"Eine Schraube musst du im Uhrzeigersinn reindrehen  - rechtsherum und mit Kraft!\"  2. \"Eine Schraube musst du genauso reindrehen wie die Oma im Reindl umrührt - rechtsherum und mit Kraft!\"  3. Eine Schraube drehst du im Uhrzeigersinn fest – rechtsherum, mit gleichmäßigem Druck!"}]'::jsonb, 'Genauso wia mas Reindl ausschmiiad!'),
  ('s-reindl-vakead-ausschmiian', 's Reindl vakead ausschmiian', '', '', '', 'Wiener Sprüche, die sitzen!', 'das Reindl verkehrt ausschmieren', '[{"kategorie": "wörtlich", "text": "\"den Topf von der anderen Seite ausschmieren\""}, {"kategorie": "fig.", "text": "etwas andersherum angehen"}, {"kategorie": "", "text": "einen anderen Ansatz wählen"}, {"kategorie": "", "text": "\"das Huhn mal von der anderen Seite rupfen\""}]'::jsonb, ''),
  ('du-kaunnst-des-problem-ned-imma-gleich-loeoesn-maunchmoi-muassd-s-reindl-hoid-vakead-ausschmiian', 'Du kaunnst des Problem ned imma gleich löösn - maunchmoi muassd s''Reindl hoid vakead ausschmiian!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Du kannst das Problem nicht immer gleich lösen – manchmal musst du das Reindl halt verkehrt ausschmieren!', '[{"kategorie": "wörtlich", "text": "\"Du kannst das Problem nicht immer gleich lösen – manchmal musst du es halt andersherum angehen!\"  2. Manchmal muss man den Teig von der anderen Seite kneten, damit er aufgeht!  3. Nicht jedes Problem ist gleich - manchmal musst du das Huhn eben von der anderen Seite rupfen!"}]'::jsonb, ''),
  ('des-saeu-is-grissn-wias-den-gaunzn-krempae-ind-haeae-ghoobm-haum', 'Des Säu is grissn, wias den gaunzn Krempä ind Hää ghoobm haum!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Das Seil ist gerissen, wie sie den ganzen Krempel in die Höhe gehoben haben!', '[{"kategorie": "wörtlich", "text": "\"Das Seil ist gerissen, als sie das ganze Ding in die Höhe hoben!\"  2. \"Beim Hochziehen der ganzen Fracht ist das Seil gerissen!\"  3. \"Das Seil ist beim Hochwuchten des ganzen Krempels plötzlich gerissen!\""}]'::jsonb, ''),
  ('ea-hod-sei-leebm-laung-nix-grissn', 'Ea hod sei Leebm laung nix grissn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er hat sein Leben lang nichts gerissen!', '[{"kategorie": "wörtlich", "text": "\"Er hat sein ganzes Leben lang nie was erreicht!\"  2. \"Er hat Zeit seines Lebens keinen Erfolg gehabt!\"  3. \"Er hat''s im Leben zu nichts gebracht!\""}]'::jsonb, 'wos reissn'),
  ('olle-reissn-si-um-de-schdoeoe', 'Olle reissn si um de Schdöö!', '', '', '', '', 'Alle reißen sich um die Stelle!', '[{"kategorie": "wörtlich", "text": "\"Alle kämpfen um diese Stelle!\"  2. \"Alle streiten sich um diese Stelle!\"  3. \"Diese freie Stelle ist sehr stark nachgefragt!\""}]'::jsonb, ''),
  ('si-um-wos-reissn', 'si um wos reissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich um etwas reißen', '[{"kategorie": "wörtlich", "text": "\"sich intensiv um etwas bemühen\""}, {"kategorie": "", "text": "\"sich um etwas streiten\""}, {"kategorie": "", "text": "\"kämpfen um etwas\""}, {"kategorie": "", "text": "\"heiß auf etwas sein\""}]'::jsonb, 'Olle reissn si um de Schdöö!'),
  ('de-faeaens-reissn-si-um-de-tickets', 'De Fääns reissn si um de Tickets!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Die Fans reißen sich um die Tickets!', '[{"kategorie": "wörtlich", "text": "\"Die Fans streiten sich um die Tickets!\"  2. \"Die Tickets sind bei den Fans heiß begehrt!\"  3. \"Die Fans kämpfen um die letzten Tickets!\""}]'::jsonb, 'si um wos reissn'),
  ('i-soogs-da-ealich-reissn-tua-i-mi-ned-drum', 'I soogs da ealich - reissn tua I mi ned drum!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich sag''s dir ehrlich - reißen tu ich mich nicht drum!', '[{"kategorie": "wörtlich", "text": "\"Ich sag''s dir ehrlich - darauf bin ich nicht wirklich scharf!\"  2. \"Ich sag''s dir ganz offen: da hab ich nicht wirklich einen Bock drauf!\"  3. \"Offen gesagt: mein Interesse hält sich in Grenzen!\""}]'::jsonb, ''),
  ('wem-wia-ausn-gsichd-grissn-sei', 'wem wia ausn Gsichd grissn sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem wie aus dem Gesicht gerissen sein', '[{"kategorie": "wörtlich", "text": "\"jemandem wie aus dem Gesicht geschnitten sein\""}, {"kategorie": "", "text": "\"jemandem zum Verwechseln ähnlich sehen\""}, {"kategorie": "", "text": "\"das Ebenbild von jemandem sein\""}]'::jsonb, 'Da Peasch is sein Voodan wiar ausn Gsicht grissn!'),
  ('da-peasch-is-sein-voodan-wiar-ausn-gsicht-grissn', 'Da Peasch is sein Voodan wiar ausn Gsicht grissn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Persch ist seinem Vater wie aus dem Gesicht gerissen!', '[{"kategorie": "wörtlich", "text": "\"Der Bursche ist seinem Vater wie aus dem Gesicht geschnitten!\"  2. \"Der Bub sieht seinem Vater zum Verwechseln ähnlich!\"  3. \"Der Junge ist das Ebenbild seines Vaters!\""}]'::jsonb, 'wem wia ausn Gsichd grissn sei'),
  ('grissn-is-s', 'Grissn is ''s!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Gerissen ist es!', '[{"kategorie": "wörtlich", "text": "\"Das wär erledigt!\"  2. \"Es ist vollbracht!\"  3. \"Das ist gelungen!\""}]'::jsonb, ''),
  ('wos-reissn', 'wos reissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'etwas reißen', '[{"kategorie": "wörtlich", "text": "\"etwas [den Erfolg] an sich reißen\" (vom mittelhochdeutschen \"rīzen\"=\"reißen\")"}, {"kategorie": "fig.", "text": "etwas erreichen, schaffen, zuwege bringen\", Erfolg haben, reüssieren"}]'::jsonb, ''),
  ('zaun1', 'Zaun1', 'der', '', '', '', 'Zaun', '[{"kategorie": "wörtlich", "text": "\"Zaun\" (vom mittelhochdeutschen \"zoun\"=\"Zaun\")"}, {"kategorie": "allg.", "text": "Abzäunung, Einfriedigung/Einfriedung, Einzäunung, Umzäunung"}]'::jsonb, ''),
  ('zaun2', 'Zaun2', 'der', '', '', '', 'Zahn', '[{"kategorie": "", "text": "\"Zahn\" (Plural: \"Zänd\", vom mittelhochdeutschen \"zant\"=\"Zahn\")"}, {"kategorie": "anat.", "text": "Zahn, Beißzahn, Kauzahn, Beißerchen, [[Zaandal]]"}]'::jsonb, ''),
  ('wem-an-zaun-reissn', 'wem an Zaun reissn', '', '', '', 'Krank & kuriert auf Wienerisch', 'jemandem einen Zahn reißen', '[{"kategorie": "wörtlich, med.", "text": "\"jemandem einen Zahn ziehen\""}, {"kategorie": "", "text": "\"bei jemandem eine Zahnextraktion durchführen\""}, {"kategorie": "", "text": "\"jemandem einen Zahn aus dem Kiefer holen\""}]'::jsonb, 'Waunn de Schmeazn schlimma wäan, miass ma da in Zaun reissn!'),
  ('waunn-de-schmeazn-schlimma-waean-miass-ma-da-in-zaun-reissn', 'Waunn de Schmeazn schlimma wäan, miass ma da in Zaun reissn!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Wenn die Schmerzen schlimmer werden, müssen wir dir den Zahn reißen!', '[{"kategorie": "wörtlich", "text": "\"Wenn sich die Schmerzen verschlimmern, müssen wir dir den Zahn rausnehmen!\"  2. \"Sollten die Schmerzen zunehmen, muss der Zahn gezogen werden!\"  3. \"Wird’s ärger, bleibt nur noch, den Zahn zu ziehen!\""}]'::jsonb, 'wem an Zaun reissn'),
  ('de-easchdn-zaandaln-suang-fia-vueue-raunzarei-und-wenig-schloof', 'De easchdn Zaandaln suang fia vüü Raunzarei und wenig Schloof!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die ersten Zanderln sorgen für viel Raunzerei und wenig Schlaf!', '[{"kategorie": "wörtlich", "text": "\"Die ersten Zähnchen sorgen für viel Quengelei und wenig Schlaf!\"  2. \"Wenn die ersten Zähne kommen, schlafen Babys häufig schlechter und quengeln in der Nacht!\"  3. \"Die ersten Zähnchen sorgen für viel Gejammer und rauben allen den Schlaf!\""}]'::jsonb, ''),
  ('de-mueuechzaandaln-brechn-meistns-schoo-im-easchdn-leebmsjoa-duach', 'De Müüchzaandaln brechn meistns schoo im easchdn Leebmsjoa duach!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Milchzähnchen brechen meist schon im ersten Lebensjahr durch!', '[{"kategorie": "wörtlich", "text": "\"Die Milchzähne kommen in der Regel bereits im ersten Lebensjahr!\"  2. \"In den ersten zwölf Monaten zeigen sich oft schon die ersten Milchzähne!\"  3. \"Bei vielen babys sind die Milchzähnchen schon vor dem ersten Geburtstag da!\""}]'::jsonb, ''),
  ('wia-ma-frisch-valiabd-woan-hob-i-zu-meina-oidn-noo-mausizaandal-gsoogd-heit-soog-i-nua-noo-schaeaefin-zu-ia', 'Wia ma frisch valiabd woan, hob I zu meina Oidn noo ''Mausizaandal'' gsoogd - heit soog I nua noo ''Schääfin'' zu ia!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wie wir frisch verliebt waren, hab ich zu meiner Alten noch ''Mausizahnderl'' gesagt - heut sag ich nur noch ''Chefin'' zu ihr!', '[{"kategorie": "wörtlich", "text": "\"Als wir frisch verliebt waren, hab ich meine Frau noch \"Mäusezähnchen\" genannt - jetzt red ich sie nur noch mit ''Chefin'' an!\"  2. \"Früher war sie mein Mausizahnderl – jetzt ist sie meine Chefin, bei der ich mich an- und abmelden muss!\"  3. \"Damals hab ich sie noch ''Mausizahnderl'' genannt - heut red ich sie nur mehr an, wenn’s sein muss!\""}]'::jsonb, ''),
  ('jetzd-hods-mi-grissn', 'Jetzd hods mi grissn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Jetzt hat es mich gerissen', '[{"kategorie": "wörtlich", "text": "\"Jetzt habe ich mich erschreckt!\"  2. \"Jetzt bin ich richtig zusammengezuckt!\"  3. \"Jetzt habe ich aber einen Schreck bekommen!\""}]'::jsonb, ''),
  ('mi-reissts', 'Mi reissts!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mich reißt''s!', '[{"kategorie": "wörtlich", "text": "\"Mich reißt es!\"  2. \"Ich zuck zusammen!\"  3. \"Ich bekomme einen Schrecken!  4. Mir fährt der Schreck durch die Glieder!"}]'::jsonb, ''),
  ('mi-beidlds', 'Mi beidlds!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mich beutelt''s!', '[{"kategorie": "wörtlich", "text": "\"Mich beutelt es durch!\"  2. \"Ich zuck zusammen!\"  3. \"Ich bekomme einen Schrecken!  4. Mir fährt der Schreck durch die Glieder!"}]'::jsonb, ''),
  ('an-kropfn-reissn', 'an Kropfn reissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Krapfen reißen', '[{"kategorie": "wörtlich", "text": "\"einen Sturz reißen\" (und dann daliegen wie ein Krapfen\")"}, {"kategorie": "allg.", "text": "\"schwer stürzen\", \"zu Boden stürzen\""}, {"kategorie": "", "text": "[[einen]] Stern reißen, [[ein]] Kipferl reißen, [[eine]] Brezen reißen"}]'::jsonb, 'Ea is aum Eis ausgrutschd und hod daunn an sauwan Kropfn grissn!'),
  ('ea-is-aum-eis-ausgrutschd-und-hod-daunn-an-sauwan-kropfn-grissn', 'Ea is aum Eis ausgrutschd und hod daunn an sauwan Kropfn grissn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er ist am Eis ausgerutscht und hat dann einen sauberen Krapfen gerissen!', '[{"kategorie": "wörtlich", "text": "\"Er ist auf dem Glatteis ausgerutscht und hat dann einen bösen Sturz hingelegt!\"  2. \"Er hat auf dem Eis den Halt verloren und dann einen ordentlichen Sturz gerissen!\"  3. \"Er ist auf dem Eis ausgerutscht, und dann hat es ihn bäuchlings hingehauen!\""}]'::jsonb, 'an Kropfn reissn'),
  ('a-kipfal-reissn', 'a Kipfal reissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein Kipferl reißen', '[{"kategorie": "wörtlich", "text": "\"einen Sturz reißen\" (und dann daliegen wie ein Kipferl)"}, {"kategorie": "allg.", "text": "\"schwer stürzen\", \"zu Boden stürzen\""}, {"kategorie": "", "text": "[[einen]] Stern reißen, [[einen]] Krapfen reißen, [[eine]] Brezen reißen"}]'::jsonb, 'Fost häd I a Kipfal grissn, owa daunn hob I mi grod noo dafaungan!'),
  ('fost-haed-i-a-kipfal-grissn-owa-daunn-hob-i-mi-grod-noo-dafaungan', 'Fost häd I a Kipfal grissn, owa daunn hob I mi grod noo dafaungan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Fast hätt'' ich ein Kipferl gerissen, aber dann hab ich mich gerade noch erfangen!', '[{"kategorie": "wörtlich", "text": "\"Fast hätt'' ich einen Sturz gerissen, aber dann hab ich mich gerade noch erfangen!\"  2. \"Fast wär ich hingeflogen, aber ich hab mich gerade noch gefangen!\"  3. \"Fast hätte ich einen Abflug gemacht - aber dann bin ich doch noch auf den Beinen gelandet!\""}]'::jsonb, 'a Kipfal reissn'),
  ('a-baroeoen-reissn', 'a Baröön reissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine Barellen reißen', '[{"kategorie": "wörtlich", "text": "\"einen Sturz reißen\" (und dann so steif daliegen wie auf der Totenbahre [Barelle])"}, {"kategorie": "allg.", "text": "\"schwer stürzen\", \"zu Boden stürzen\""}, {"kategorie": "", "text": "[[einen]] Stern reißen, [[einen]] Krapfen reißen, [[eine]] Brezen reißen"}]'::jsonb, 'I hob mit mein Eisn a soiche Baröön grissn, dass I noocha fünf Wochn auf da Intensivschdation gleeng bin!'),
  ('i-hob-mit-mein-eisn-a-soiche-baroeoen-grissn-dass-i-noocha-fuenf-wochn-auf-da-intensivschdation-gleeng-bin', 'I hob mit mein Eisn a soiche Baröön grissn, dass I noocha fünf Wochn auf da Intensivschdation gleeng bin!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich hab mit meinem Eisen eine solche Barelle gerissen, dass ich nachher fünf Wochen auf der Intensivstation gelegen bin!', '[{"kategorie": "wörtlich", "text": "\"Ich hab mit meinem Motorrad einen derartigen Sturz gerissen, dass ich nachher fünf Wochen auf der Intensivstation gelegen bin!\"  2. \"Ich hab mit dem Motorrad so einen schlimmen Sturz gebaut, dass ich danach fünf Wochen auf der Intensivstation war!\"  3. \"Ich hab mit dem Motorrad einen brutalen Abflug gemacht – danach lag ich fünf Wochen im Koma!\""}]'::jsonb, 'a Baröön reissn'),
  ('an-schdean-reissn', 'an Schdean reissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Stern reißen', '[{"kategorie": "wörtlich", "text": "\"einen Sturz reißen\" (und dann mit ausgebreiteten Gliedmaßen sternförmig daliegen)"}, {"kategorie": "allg.", "text": "\"schwer stürzen\", \"zu Boden stürzen\""}, {"kategorie": "", "text": "[[eine]] Brezen reißen, [[eine]] Pletschen reißen, [[eine]] Barellen reißen"}]'::jsonb, 'An Schdean reissn ghead beim Schifoan dazua wia da Schnää zua Pistn!'),
  ('an-schdean-reissn-ghead-beim-schifoan-dazua-wia-da-schnaeae-zua-pistn', 'An Schdean reissn ghead beim Schifoan dazua wia da Schnää zua Pistn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Einen Stern reißen gehört beim Skifahren dazu wie der Schnee zur Piste!', '[{"kategorie": "wörtlich", "text": "\"Einen Sturz zu reißen gehört beim Skifahren dazu wie der Schnee zur Piste!\"  2. \"Ein Abflug gehört beim Skifahren genauso dazu wie der Schnee zur Piste!\"  3. \"Ein Stern ist beim Skifahren genauso unvermeidlich wie der Schnee auf der Piste!\""}]'::jsonb, 'an Schdean reissn'),
  ('a-kraxn-reissn', 'a Kraxn reissn', '', '', '', 'Tod und Sterben auf Wienerisch', 'eine Kraxen reißen', '[{"kategorie": "wörtlich", "text": "\"kaputtgehen wie das Gestell einer [[Kraxen]] [=\"Rückentragekorb\"]\""}, {"kategorie": "allg.", "text": "sterben, das Zeitliche segnen, [[ins]] Gras beißen, [[ein]] Bankerl reißen, [[die]] Patschen strecken, [[sich]] die Erdäpfel von unten anschauen, [[den]] Löffel abgeben"}]'::jsonb, 'Sein Fuufzga hoda noo gfeiad - owa zwaa Toog schbääda hoda daunn a Kraxn grissn!'),
  ('sein-fuufzga-hoda-noo-gfeiad-owa-zwaa-toog-schbaeaeda-hoda-daunn-a-kraxn-grissn', 'Sein Fuufzga hoda noo gfeiad - owa zwaa Toog schbääda hoda daunn a Kraxn grissn!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Seinen Fünfziger hat er noch gefeiert - aber zwei Tage später hat er dann eine Krax''n g''rissen!', '[{"kategorie": "wörtlich", "text": "\"Seinen 50. Geburtstag hat er noch gefeiert, doch zwei Tage später ist er verstorben!\"  2. \"Seinen Fünfziger hat er noch gefeiert - aber zwei Tage später hat er dann den Löffel abgegeben!\"  3. \"Er feierte noch seinen 50er – doch zwei Tage später hat er ins Gras gebissen!\""}]'::jsonb, 'a Kraxn reissn'),
